var e=JSON.parse(`{"wrist-circles":{"name":"Cercles de poignets","description":"Tenez-vous droit, coudes souples et avant-bras devant vous. Dessinez des cercles lents avec les deux poignets, quatre temps dans un sens et quatre dans l'autre, en gardant les doigts relâchés.","goodFor":"Échauffe les poignets et les avant-bras qui font la plupart du travail avec chaque agrès.","alignmentCues":["Les coudes restent immobiles ; seuls les poignets bougent.","Gardez les cercles grands et fluides."],"commonMistakes":["Aller trop vite dans les cercles, ce qui les transforme en petits coups secs."]},"arm-circles":{"name":"Cercles de bras","description":"Pieds écartés à la largeur des hanches, bras tendus. Balancez les deux bras en grands cercles vers l'avant pendant quatre temps, puis vers l'arrière pendant quatre, en laissant les omoplates glisser.","goodFor":"Ouvre les épaules pour les rotations de staff et le travail du hoop au-dessus de la tête.","alignmentCues":["Les côtes restent basses quand les bras passent au-dessus de la tête.","Expirez sur le mouvement descendant."]},"shoulder-rolls":{"name":"Rotations d'épaules","description":"Bras relâchés le long du corps. Montez les épaules vers les oreilles, roulez-les vers l'arrière et vers le bas, et répétez en boucle lente.","goodFor":"Libère les tensions qui rendent les lancers raides et courts."},"neck-rolls":{"name":"Demi-cercles de nuque","description":"Baissez le menton vers la poitrine et balayez-le lentement d'une épaule à l'autre en demi-cercle. Évitez de basculer la tête en arrière.","goodFor":"Détend la nuque avant de regarder les lancers vers le haut pendant de longues périodes.","avoidIf":["Blessure à la nuque ou vertiges lors des mouvements de tête."]},"hip-circles":{"name":"Cercles de hanches","description":"Mains sur les hanches, genoux souples. Faites des cercles lents avec les hanches dans un sens pendant deux mesures et dans l'autre pendant deux, en gardant la tête droite.","goodFor":"Prépare les hanches pour le hoop à la taille et le corps pour le flow."},"torso-twists":{"name":"Torsions du buste","description":"Pieds écartés, bras relâchés. Tournez les côtes à gauche et à droite et laissez les bras se balancer et s'enrouler autour de vous comme des manches vides.","goodFor":"Réveille la rotation pour les weaves au staff et les passes au hoop."},"knee-bounce":{"name":"Rebonds de genoux","description":"Tenez-vous debout, pieds sous les hanches, et rebondissez doucement sur les genoux à chaque temps, bras balancés librement. Trouvez la musique dans vos jambes.","goodFor":"Met le rythme dans votre corps avant de prendre un agrès."},"one-ball-toss":{"name":"Lancer d'une balle","description":"Tenez une balle dans la main droite à hauteur de taille. Ramenez-la vers l'intérieur, puis lancez-la en arc qui culmine juste au-dessus du niveau des yeux et retombe dans la main gauche. Renvoyez-la de la même façon. Gardez les yeux sur le sommet de l'arc, pas sur vos mains.","goodFor":"Construit l'arc sur lequel repose chaque figure de jonglage.","alignmentCues":["Coudes le long du corps, avant-bras à l'horizontale.","Le sommet est à la même hauteur à chaque lancer.","Attrapez à hauteur de taille et laissez la main amortir un peu."],"commonMistakes":["Lancer vers l'avant, ce qui vous oblige à avancer après la balle.","Regarder les mains au lieu du sommet."]},"two-ball-exchange":{"name":"Échange à deux balles","description":"Une balle dans chaque main. Lancez la balle droite dans son arc ; quand elle culmine, lancez la balle gauche en dessous, à l'intérieur. Attrapez les deux et marquez une pause. Puis commencez avec la main gauche.","goodFor":"Enseigne l'échange : le deuxième lancer part quand le premier culmine.","alignmentCues":["Deuxième lancer au sommet, jamais en avance.","Lancez la deuxième balle à l'intérieur de la première."],"commonMistakes":["Passer la deuxième balle d'une main à l'autre au lieu de la lancer.","Lancer les deux en même temps."]},"cascade":{"name":"Cascade à trois balles","description":"Deux balles dans la main droite, une dans la gauche. Lance depuis la droite ; au sommet, lance depuis la gauche ; au sommet, relance depuis la droite. Chaque lancer tombe sur le temps, en croisant vers l'autre main dans un arc en 8.","goodFor":"Le motif fondamental de la jonglerie.","modifications":["Travaille le flash : trois lancers, trois rattrapés, stop."],"deepen":["Jongle sur un tempo plus rapide avec des sommets plus bas.","Compte 20 rattrapés sans faire tomber."],"alignmentCues":["Lance depuis l'intérieur, rattrape à l'extérieur.","Sommets au niveau des yeux.","Tiens-toi contre un mur si tu avances sans cesse."],"commonMistakes":["Lancer vers l'avant et courir après le motif.","Se précipiter dès qu'un lancer rate."]},"reverse-cascade":{"name":"Cascade inversée","description":"La cascade à l'envers : chaque balle est lancée depuis l'extérieur, par-dessus le motif, et retombe au centre dans l'autre main.","goodFor":"Entraîne les lancers depuis l'extérieur et ouvre la voie à des figures comme le Mills Mess.","alignmentCues":["Les lancers passent au-dessus de la balle qui arrive.","Rattrape au centre."]},"siteswap-423":{"name":"423","description":"Un motif à trois balles : un lancer haut de la même main (4), une balle tenue (2), puis un lancer de cascade (3). Le 4 monte du même côté ; le 2 est simplement tenu pendant un temps.","goodFor":"Ta première figure en siteswap : apprend les lancers hauts et les tenues."},"siteswap-441":{"name":"441","description":"Deux lancers hauts qui restent de leur côté (4, 4) suivis d'un zip rapide d'une main à l'autre (1).","goodFor":"Développe le timing entre lancers hauts et passes rapides."},"two-in-one":{"name":"Deux dans une main","description":"Jongle deux balles dans une main en colonnes côte à côte ou en petits cercles vers l'extérieur, un lancer tous les deux temps. Travaille chaque main.","goodFor":"La brique de base de la jonglerie à quatre balles."},"siteswap-531":{"name":"531","description":"Un lancer croisé très haut (5), un lancer de cascade (3) et un zip rapide (1). Le 5 monte pendant que les deux autres balles continuent de travailler en dessous.","goodFor":"Contrôle de la hauteur et figure à trois balles qui impressionne."},"shower":{"name":"Douche à trois balles","description":"Les balles voyagent en cercle : la main droite lance chaque balle haut vers la gauche, et la main gauche renvoie chacune directement vers la droite.","goodFor":"Motif circulaire classique ; entraîne les passes rapides d'une main à l'autre."},"mills-mess":{"name":"Mills Mess","description":"Une cascade à trois balles où les bras ne cessent de se croiser et se décroiser, chaque lancer partant du côté opposé du corps. Les trajectoires des balles dessinent un motif tissé.","goodFor":"Un classique qui impressionne le public et affine la coordination."},"four-ball-fountain":{"name":"Fontaine à quatre balles","description":"Chaque main jongle deux balles dans sa propre colonne, les mains alternant les lancers pour que le motif ne croise jamais.","goodFor":"Ton premier motif à quatre balles."},"sync-fountain":{"name":"Fontaine synchrone","description":"Quatre balles avec les deux mains qui lancent exactement au même moment, chacune de son côté.","goodFor":"Développe la symétrie et mène aux figures synchrones."},"five-ball-cascade":{"name":"Cascade à cinq balles","description":"La cascade à cinq balles : des lancers hauts et rapides dans un grand motif croisé. Comptez des mois de pratique.","goodFor":"Un cap pour les jongleurs dévoués."},"staff-wheel-spin":{"name":"Rotation de bâton à deux mains en roue","description":"Tenez le bâton au milieu avec les deux mains, paumes vers le bas, à hauteur de poitrine. Faites-le tourner à votre côté comme une roue en passant la rotation d'une main à l'autre, en le gardant près du corps.","goodFor":"La première rotation de bâton ; développe la prise et la rotation du poignet.","alignmentCues":["Le bâton reste parallèle à votre corps, sans jamais s'incliner.","Prise souple : laissez-le rouler entre les doigts."],"props":["bâton"],"commonMistakes":["Serrer trop fort, ce qui bloque la rotation.","Incliner le plan vers l'avant."]},"staff-front-spin":{"name":"Moulin à vent avant","description":"Faites tourner le bâton devant vous comme une hélice, dans le plan du mur, en le passant fluidement d'une main à l'autre autour de son centre.","goodFor":"Ajoute le plan du mur et le passage main par main.","props":["bâton"]},"staff-figure-8":{"name":"Tissage en huit","description":"Faites tourner le bâton dans le plan de la roue sur votre côté droit, puis croisez-le vers votre côté gauche et faites-le tourner là, en traçant un huit devant vous.","goodFor":"Relie les deux côtés du corps ; la base du flow au bâton.","alignmentCues":["Changez de côté quand les embouts passent près du sol.","Faites pivoter légèrement le torse à chaque changement de côté."],"props":["bâton"]},"staff-pass-through":{"name":"Passage à travers","description":"Tournez dans le plan du mur mais lâchez à chaque demi-tour : une main relâche le bâton et l'autre le rattrape au centre, de sorte que le bâton passe entre vos mains.","goodFor":"Enseigne le timing du lâcher et de la réception.","props":["bâton"]},"staff-one-hand-spin":{"name":"Rotation à une main","description":"Faites tourner le bâton devant vous avec une main, en le faisant rouler sur le dos de la main et entre les doigts. Entraînez les deux mains.","goodFor":"Force des doigts et du poignet ; libère l'autre main pour les figures.","props":["bâton"]},"staff-helicopter":{"name":"Hélicoptère au-dessus de la tête","description":"Levez le bâton au-dessus de la tête et faites-le tourner à plat dans le plan du sol avec une main, comme les pales d'un hélicoptère.","goodFor":"Introduit le plan du sol.","props":["bâton"]},"staff-butterfly":{"name":"Papillon","description":"Tournez devant vous, puis repliez le bâton derrière votre épaule et ressortez-le, en alternant avant et arrière de chaque côté comme des ailes.","goodFor":"Mobilité des épaules et transition fluide d'avant en arrière.","props":["bâton"]},"staff-behind-back-pass":{"name":"Passage dans le dos","description":"Passez le bâton en rotation d'une main à l'autre derrière votre dos au point bas de la rotation, puis ramenez-le devant.","goodFor":"Enroulements du corps et passages spectaculaires.","props":["bâton"]},"staff-isolation":{"name":"Isolation de staff","description":"Tiens le staff près d'une extrémité et fais tourner ta main autour du centre du staff, pour que le centre semble rester fixe dans l'air pendant que le staff tourne autour de lui.","goodFor":"Travail d'illusion et trajectoires de main précises.","props":["bâton"]},"staff-antispin-flower":{"name":"Antispin quatre pétales","description":"Fais tourner ta main dans un sens pendant que le staff tourne dans l'autre sens trois fois plus vite, pour que le staff dessine une fleur à quatre pétales.","goodFor":"La fleur VTG signature ; contrôle profond du timing.","props":["bâton"]},"staff-neck-roll":{"name":"Roulé de cou","description":"Lâche le staff sur le haut de tes épaules et laisse-le rouler sur la nuque jusqu'à l'autre main. Commence doucement avec un staff rembourré.","goodFor":"Contact staff : le staff se déplace sur le corps sans les mains.","avoidIf":["Douleur à la nuque."],"props":["bâton"]},"hoop-waist":{"name":"Hoop à la taille","description":"Tiens-toi avec un pied légèrement devant l'autre. Place le cerceau contre ton bas du dos, lance-le autour de ta taille et pousse le ventre vers l'avant puis vers l'arrière (pas en cercles) chaque fois que le cerceau passe devant toi.","goodFor":"La première compétence au hoop ; développe le rythme du centre.","modifications":["Utilise un cerceau plus grand et plus lourd : il tourne plus lentement."],"alignmentCues":["Bascule d'avant en arrière, pas en cercles.","Pousse sur le cerceau quand il passe sur ton ventre."],"props":["cerceau"],"commonMistakes":["Faire tourner les hanches comme une danseuse de hula.","Un cerceau trop petit ou trop léger."]},"hoop-hand-spin":{"name":"Spin de main","description":"Tiens le cerceau devant toi avec la main à l'intérieur, pouce vers le haut. Pousse-le pour qu'il tourne autour de la toile de ta main, en gardant le cerceau à plat devant toi.","goodFor":"Base du hoop off-body.","props":["cerceau"]},"hoop-chest":{"name":"Hoop à la poitrine","description":"Lève les bras au-dessus de la tête et fais tourner le cerceau autour de la poitrine, en balançant la cage thoracique d'avant en arrière tout en gardant les hanches calmes.","goodFor":"Isolation de la cage thoracique et contrôle du haut du corps.","props":["cerceau"]},"hoop-lasso":{"name":"Lasso","description":"Tiens le cerceau au-dessus de la tête et fais-le tourner à plat comme un lasso, le cerceau tournant autour de ta main.","goodFor":"Contrôle du plan au sol au-dessus de la tête.","props":["cerceau"]},"hoop-wedgie":{"name":"Wedgie","description":"Fais tourner le cerceau dans le plan du mur et attrape-le dans le creux entre le pouce et les doigts, en le laissant rouler et basculer là avant de le relancer.","goodFor":"Contrôle de la prise et transition fluide.","props":["cerceau"]},"hoop-knees":{"name":"Hoop aux genoux","description":"Pieds joints, garde le cerceau en rotation autour de tes genoux en poussant les genoux d'avant en arrière.","goodFor":"Hooping du bas du corps et escalator.","props":["cerceau"]},"hoop-pass":{"name":"Passe main à main","description":"Fais tourner le hoop devant toi et passe-le d'une main à l'autre à chaque révolution, en gardant le plan stable.","goodFor":"Enchaîne les tricks hors du corps des deux côtés.","props":["cerceau"]},"hoop-isolation":{"name":"Isolation au hoop","description":"Déplace ta main autour du hoop pour que son centre reste fixe dans l'air devant toi pendant que le hoop tourne autour de ce point.","goodFor":"L'illusion classique au hoop.","props":["cerceau"]},"hoop-escalator":{"name":"Escalator","description":"Garde le hoop en rotation en le faisant descendre de la taille aux genoux puis remonter à la poitrine, une zone du corps par mesure.","goodFor":"Relie toutes les zones du body hooping en un seul flow.","props":["cerceau"]},"hoop-neck":{"name":"Hooping au cou","description":"Incline légèrement la tête et laisse un hoop léger tourner autour du cou, guidé par de petites impulsions de la tête et des épaules.","goodFor":"Un move de show qui travaille des impulsions petites et précises.","avoidIf":["Douleur au cou."],"props":["cerceau"]},"shake-out":{"name":"Secouer les bras","description":"Pose les props et secoue les mains et les avant-bras. Laisse tomber les épaules.","goodFor":"Une courte remise à zéro entre les runs difficiles."},"breathe":{"name":"Respirer et se recentrer","description":"Reste immobile, ferme ou adoucis les yeux, et respire lentement par le nez puis par la bouche.","goodFor":"Fait baisser le rythme cardiaque et dissipe la frustration après les drops.","breathCue":"Inspire en quatre, expire en quatre."}}`),t={"warmup-mobility":{name:`Échauffement flow`,description:`Poignets, épaules, colonne et hanches assouplis sur un beat régulier. À faire avant toute session avec un prop.`,focus:`Échauffement · mobilité`},"first-throws":{name:`Premiers lancers`,description:`Une balle qui décrit un arc d'une main à l'autre à hauteur des yeux, puis l'échange à deux balles d'où naît chaque figure.`,focus:`Jonglage · fondamentaux`},"cascade-builder":{name:`Construire la cascade`,description:`Des échanges à deux balles enchaînés jusqu'à ce que la troisième balle rejoigne : courtes séries de cascade, reset, on repart.`,focus:`Jonglage · fondamentaux`},"juggling-tempo-ladder":{name:`Échelle de tempo en cascade`,description:`La cascade à trois tempos, quelques beats plus rapide à chaque palier. Lance plus bas pour les paliers rapides.`,focus:`Jonglage · tempo`},"siteswap-sampler":{name:`Échantillon de siteswap`,description:`Cascade vers 423, 441 et 531, avec la reverse cascade et la shower pour te purifier le palais. Chaque figure commence et se termine en cascade.`,focus:`Jonglage · figures`},"four-ball-session":{name:`Session à quatre balles`,description:`Deux dans une main de chaque côté, la fontaine à quatre balles, puis la fontaine synchrone.`,focus:`Jonglage · nombres`},"juggling-combo-flow":{name:`Enchaînement de jonglage`,description:`Un long set fluide : cascade, cascade inversée, Mills mess et les siteswaps enchaînés en un seul morceau de musique.`,focus:`Jonglage · enchaînements`},"staff-first-spins":{name:`Premiers spins au staff`,description:`Le wheel spin à côté du corps, puis le front spin. Des tours lents et réguliers, un par temps.`,focus:`Staff · bases`},"staff-foundations":{name:`Bases du staff`,description:`Wheel spin, front spin, figure 8 et le passage main à main reliés sur le temps.`,focus:`Staff · bases`},"staff-flow-weave":{name:`Weave fluide au staff`,description:`Figure 8 en butterfly, spins à une main et le helicopter, enchaînés pour que le staff ne s'arrête jamais.`,focus:`Bâton · flow`},"staff-isolation-lab":{name:`Labo d'isolations au staff`,description:`Isolations et antispin flower à un tempo plus lent, avec des passes dans le dos entre les deux.`,focus:`Staff · technique`},"staff-advanced-flow":{name:`Flow avancé au staff`,description:`Tout le vocabulaire en un seul long morceau : weaves, wraps, isolations et le neck roll.`,focus:`Bâton · flow`},"hoop-first-spins":{name:`Premiers spins au hoop`,description:`Hoop à la taille avec une poussée avant-arrière, puis le hoop qui tourne autour d'une main.`,focus:`Hoop · bases`},"hoop-body-flow":{name:`Flow on-body au hoop`,description:`Faire monter le hoop jusqu'à la poitrine, descendre aux genoux et revenir à la taille, sans s'arrêter.`,focus:`Hoop · sur le corps`},"hoop-off-body":{name:`Hoop off-body`,description:`Hand spins, lasso, wedgies et passes, pour finir avec des isolations qui immobilisent le hoop dans l'espace.`,focus:`Hoop · hors du corps`},"hoop-full-flow":{name:`Flow complet au hoop`,description:`On-body et off-body ensemble : escalators, neck hooping et les figures off-body en un seul long flow.`,focus:`Cerceau · flow`},"daily-mixed-flow":{name:`Flow mixte quotidien`,description:`Un peu de chaque art : cascade, spins au staff et hoop, avec un mouvement de mobilité entre les agrès.`,focus:`Mixte · pratique`}},n=JSON.parse(`{"start-here":{"title":"Commence ici : ta première semaine de flow","summary":"Choisis un agrès, pratique dix minutes par jour sur le temps, et laisse l'arbre de déblocage te dire ce qui vient ensuite.","imageAlt":"Figure 3D lançant une seule balle de jonglage d'une main à l'autre","body":["De l'extérieur, les arts du flow ressemblent à de la magie : des balles suspendues dans l'air, un bâton qui se transforme en flou, un cerceau qui orbite autour d'une danseuse qui semble à peine bouger. De l'intérieur, c'est un empilement de très petites compétences, chacune apprenable en un après-midi, superposées jusqu'à ce que l'ensemble paraisse sans effort. Votre première semaine concerne le bas de cet empilement.","Choisissez un agrès pour commencer. La jonglerie enseigne le timing et la coordination œil-main ; le bâton enseigne les plans et les changements de main fluides ; le cerceau enseigne le rythme à travers tout le corps. Vous pouvez apprendre les trois, mais un à la fois garde votre attention là où se trouve le progrès. L'arbre des Récompenses montre chaque mouvement pour chaque art, du premier lancer ou spin aux figures avancées, et ouvre les suivants quand vous maîtrisez ce sur quoi ils se construisent.","Pratiquez peu et souvent. Dix minutes concentrées par jour valent mieux qu'une heure le dimanche, car la coordination se consolide entre les sessions, surtout pendant le sommeil. Une courte routine depuis la page Routines, un échauffement, et quelques pas comptés de votre mouvement actuel constituent une pratique complète.","Pratiquez en rythme dès le premier jour. Chaque mouvement dans SynthFlow est compté en mesures à un tempo, avec de la musique ou des percussions générées qui correspondent. Le beat vous donne quelque chose à quoi vous accrocher quand l'agrès ne coopère pas, et il rend le progrès mesurable : une série propre à 90 BPM cette semaine, 100 la semaine prochaine.","Attendez-vous à faire tomber. Tout le monde fait tomber, y compris les professionnels en répétition. Une chute vous dit quel lancer ou quelle réception demande de l'attention ; elle ne dit rien sur le talent. Ramassez l'agrès, attendez le prochain temps fort, et repartez. À la fin de la semaine, vous aurez un mouvement que vous pouvez faire sans réfléchir, et c'est le moment où le flow commence."]},"counting-and-the-beat":{"title":"Les comptes, les mesures et le beat","summary":"Pourquoi chaque mouvement est compté en mesures à un tempo, et comment caler vos lancers et vos spins sur la musique.","imageAlt":"Figure 3D jonglant une cascade à trois balles avec des arcs dessinés au-dessus des mains","body":["La musique est faite de beats groupés en mesures, généralement quatre beats par mesure. Les mouvements de flow sont faits de cycles : un lancer de chaque main, un demi-tour du bâton, une orbite du cerceau. Quand un cycle tombe sur le beat, le mouvement et la musique ne font plus qu'un. C'est pourquoi SynthFlow mesure chaque pas de routine en mesures plutôt qu'en secondes, et pourquoi chaque mouvement indique combien de beats prend un cycle.","Dans une cascade à trois balles, chaque lancer tombe sur un beat, en alternant droite et gauche. Dans un front spin au bâton, un demi-tour prend généralement un beat. Le hooping à la taille correspond souvent à une orbite par beat à un tempo détendu. Les comptes dans le lecteur nomment ce qui se passe à chaque beat, et la figure 3D bouge exactement sur la même horloge que l'audio, pour que vous puissiez la copier en rythme.","Le tempo se mesure en battements par minute (BPM). Chaque mouvement a une plage confortable : assez lent pour rester propre, assez rapide pour que l'agrès garde son élan. En dessous de la plage, les agrès en rotation calent et les lancers montent si haut qu'ils dérivent ; au-dessus, vous commencez à vous précipiter et à faire tomber. Le builder vous avertit quand un pas sort de la plage de son mouvement.","Commencez chaque pas sur le temps fort, le « un » de la mesure. Le décompte vous donne une mesure pour mettre l'agrès en mouvement avant que les mesures comptées ne commencent. Si vous perdez le beat, ne le poursuivez pas : arrêtez-vous, écoutez le prochain « un », et revenez. Les musiciens appellent cela retrouver le haut de la mesure, et ça marche aussi pour les flow artists.","Compter à voix haute pendant quelques sessions aide plus qu'il n'y paraît. Dire « un, deux, trois, quatre » en jonglant lie le rythme à votre souffle et à votre voix, pour qu'il survive quand la figure devient difficile. Une fois que les comptes vivent dans votre corps, désactivez les comptes parlés dans les Réglages et laissez la musique vous porter."]},"tempo-ladders":{"title":"Échelles de tempo : lent c'est fluide, fluide c'est rapide","summary":"Montez de quelques BPM à la fois depuis un tempo que vous maîtrisez proprement, et redescendez dès que la forme se casse.","imageAlt":"Figure 3D faisant tourner un bâton devant le corps dans le plan du mur","body":["Une échelle de tempo, c'est le même mouvement répété à des tempos croissants : huit mesures à 80 BPM, huit à 88, huit à 96, et ainsi de suite. C'est la façon la plus fiable de rendre un mouvement plus rapide sans le rendre plus brouillon, et plusieurs routines intégrées sont construites autour de ça.","Commencez sur un barreau que vous pouvez faire proprement, même s'il semble trop facile. Le but du barreau du bas n'est pas le défi ; c'est de répéter la forme correcte pour que ce soit elle qui accélère. Montez d'un petit palier, environ cinq à dix pour cent. Les grands sauts changent le mouvement : les lancers deviennent plus bas, les spins plus superficiels, et vous finissez par pratiquer un autre trick.","Arrêtez de monter quand la forme se casse, pas quand vous faites tomber. Surveillez les premiers signes : des sommets qui deviennent inégaux, le bâton qui dérive hors de son plan, le cerceau qui monte ou descend. Ce sont les signaux pour redescendre d'un barreau et recommencer. Terminer une échelle sur une série propre à un tempo juste sous votre limite apprend ce tempo à votre corps ; terminer sur un crash apprend le crash.","Les tempos lents sont plus difficiles qu'ils n'en ont l'air pour les agrès en rotation, car l'agrès a moins d'élan pour le porter. Si un bâton ou un cerceau cale au bas de sa plage, gardez le tempo et élargissez légèrement le mouvement, ou prenez-le en half time avec la musique : un cycle tous les deux beats.","Suivez votre meilleur tempo propre pour chaque mouvement dans Progrès. Voir ce nombre grimper au fil des semaines est une bonne motivation, et cela montre aussi quand un mouvement a plafonné et a besoin d'un autre exercice plutôt que de plus de la même chose."]},"siteswap-notation":{"title":"Siteswap : la jonglerie écrite en chiffres","summary":"Chaque chiffre indique combien de beats plus tard une balle est relancée ; les chiffres impairs croisent, les pairs restent, et la moyenne est le nombre de balles.","imageAlt":"Figure 3D jonglant le siteswap 441 avec deux lancers hauts et un zip rapide","body":["Les figures de jonglerie sont difficiles à décrire en mots et faciles à décrire en chiffres. Le siteswap, développé indépendamment au milieu des années 1980 par des jongleurs à Cambridge, à Caltech et à Santa Cruz, écrit une figure comme une séquence répétée de chiffres. C'est ainsi que les jongleurs partagent des figures, vérifient si une idée peut fonctionner, et découvrent des tricks que personne n'a essayés. SynthFlow l'utilise pour animer chaque figure de jonglerie depuis le même moteur.","Imaginez les mains lançant en alternance à chaque beat : droite, gauche, droite, gauche. Chaque chiffre d'un siteswap indique combien de beats à partir de maintenant la balle lancée sur ce beat sera relancée. Un 3 revient trois beats plus tard ; comme trois est impair, il atterrit dans l'autre main. Une cascade à trois balles n'est que 3, 3, 3, 3 à l'infini, écrit simplement 3. Un 4 revient quatre beats plus tard dans la même main, c'est la fontaine à quatre balles.","Les petits chiffres ont des significations spéciales. Un 2 revient dans la même main deux beats plus tard, ce qui en pratique signifie tenir la balle un instant. Un 1 croise vers l'autre main au beat suivant, un zip rapide droit à travers. Un 0 est une main vide. Les chiffres plus grands sont des lancers plus hauts : un 5 est un grand lancer croisé.","Lisez une figure chiffre par chiffre. Dans 441, deux lancers restent de leur propre côté tandis qu'une troisième balle zip à travers en dessous. Dans 531, un lancer croisé haut monte tandis qu'un lancer de cascade et un zip font bouger les deux autres balles. Dans 423, un lancer à hauteur de fontaine, une balle tenue et un lancer de cascade se relaient.","Le théorème de la moyenne vous dit combien de balles une figure nécessite : additionnez les chiffres et divisez par leur nombre. 441 fait 9 sur trois chiffres, donc trois balles. Si la moyenne n'est pas un nombre entier, la séquence ne peut pas être jonglée. Une seconde vérification est que deux balles ne peuvent pas atterrir dans la même main sur le même beat, c'est ainsi que les jongleurs repèrent les figures impossibles avant de les essayer.","Le siteswap a aussi une notation pour les deux mains lançant ensemble, écrite entre parenthèses comme (4,4), et pour lancer deux balles d'une main en même temps, écrite entre crochets. Vous n'avez besoin de rien de tout cela pour bien jongler, mais une fois que les chiffres font tilt, chaque nouveau nom de figure commence à s'expliquer de lui-même. Ouvrez le glossaire Flow pour les chiffres individuels."]},"planes-and-geometry":{"title":"Les plans : mur, roue et sol","summary":"Les agrès en rotation vivent dans des plans plats ; garder le plan propre est l'essentiel de ce qui rend un bâton ou un cerceau net.","imageAlt":"Figure 3D tissant un bâton en figure-8 des deux côtés du corps","body":["Un bâton ou un cerceau en rotation balaie une surface plate, appelée son plan. Les flow artists décrivent trois plans de base par rapport au corps. Le plan du mur est devant vous, comme une vitre contre laquelle vous pourriez poser les paumes. Le plan de la roue est à côté de vous, comme une roue de charrette qui tourne le long de votre flanc. Le plan du sol est horizontal, parallèle au sol, comme dans un helicopter au-dessus de la tête ou un lasso.","Les plans propres sont ce que le public lit comme de la compétence. Un bâton qui vacille hors de son plan paraît incertain même s'il ne tombe jamais ; un cerceau qui reste parfaitement plat pendant un pass paraît sans effort. La plupart du travail précoce concerne discrètement les plans : empêcher les poignets de se tordre, empêcher les coudes de s'écarter, et laisser les épaules bouger l'agrès plutôt que les mains.","Beaucoup de tricks se définissent par le changement de plan. Un weave en figure-8 fait passer le bâton du plan de la roue d'un côté au plan de la roue de l'autre. Un butterfly le plie derrière l'épaule et le ramène. Un escalator fait monter et descendre un cerceau le long du corps tandis que son plan reste horizontal. Apprendre où chaque mouvement commence et finit dans l'espace, c'est ainsi que vous les reliez en flow.","Le visualiseur 3D peut dessiner le plan pendant que vous pratiquez. Activez-le en apprenant un nouveau spin et comparez : votre bâton penche-t-il vers vous en haut ? Le cerceau plonge-t-il à l'avant ? Un miroir ou une caméra de téléphone montre la même chose. Regarder depuis la vue de côté est particulièrement utile pour les mouvements dans le plan du mur, car l'inclinaison est invisible de face.","Les plans aident aussi pour la sécurité et l'espace. Avant une session, vérifiez que chaque plan que vous allez utiliser est dégagé : le mur devant, les murs à côté, et le plafond au-dessus pour les mouvements dans le plan du sol et au-dessus de la tête. Un plan propre sans rien dedans est un plan confiant."]},"spin-and-antispin":{"title":"Spin, antispin et isolations","summary":"La façon dont l'agrès tourne par rapport à la main donne trois familles de mouvement : spin, antispin et isolation.","imageAlt":"Figure 3D dessinant une fleur antispin à quatre pétales avec un staff","body":["Quand tu fais tourner un agrès en mouvement circulaire, deux rotations se produisent en même temps : ta main parcourt un cercle, et l'agrès tourne autour de son propre centre. La théorie du flow nomme les mouvements selon la relation entre ces deux rotations. C'est le même vocabulaire pour le staff, le hoop et le poi, c'est pourquoi les compétences se transfèrent si bien entre les agrès.","En spin, parfois appelé inspin, l'agrès tourne dans le même sens que le cercle de la main. C'est la direction naturelle ; la plupart des premiers spins sont des inspins sans que personne ne les nomme ainsi. La forme tracée est une fleur dont les pétales pointent vers l'extérieur.","En antispin, l'agrès tourne dans le sens opposé au cercle de la main. Ça paraît étrange au début, comme se taper la tête et se frotter le ventre, mais ça dessine la fleur à pétales classique. Le nombre de pétales dépend du nombre de rotations de l'agrès par cercle de main : trois contre-rotations par cercle donnent quatre pétales, ce qui est l'Antispin à Quatre Pétales dans l'arbre du staff.","Une isolation est le cas particulier où la main tourne de sorte qu'un point de l'agrès semble figé dans l'espace. Avec un staff, le centre reste immobile pendant que les extrémités balayent autour ; avec un hoop, le centre de l'anneau ou un point du bord reste en place. Les isolations donnent l'impression que l'agrès flotte et que le corps orbite autour. Elles exigent des trajectoires de main précises, ce qui en fait un excellent entraînement pour toutes les autres figures.","Apprends-les lentement et en rythme. L'antispin surtout bénéficie d'un tempo bien en dessous de ta vitesse normale, avec des comptes qui nomment où l'agrès doit se trouver : haut, côté, bas, côté. Utilise le ghost dans la vue 3D pour voir la position de la prochaine mesure, et la traînée pour vérifier si ta fleur a des pétales réguliers.","Une fois que spin, antispin et isolation sont familiers dans un plan, essaie-les dans un autre. La théorie reste la même et ton corps apprend que le plan n'est qu'un réglage, ce qui est un grand pas vers l'improvisation du flow."]},"sequencing":{"title":"Comment se construisent les routines de flow","summary":"Échauffe-toi, travaille un focus avec des enchaînements qui coulent, garde les sauts de tempo petits, et termine par un retour au calme facile.","imageAlt":"Figure 3D faisant passer un hoop de main en main devant le corps","body":["Une bonne routine de flow a la même forme qu'un bon set musical : une ouverture qui réchauffe la salle, un milieu qui monte, et une fin qui laisse tout le monde respirer. Les routines intégrées de SynthFlow suivent cette forme, et le co-pilote du builder vérifie la tienne par rapport à elle.","Commence par un échauffement. Les cercles de poignets, les cercles de bras et les rotations d'épaules amènent les articulations que tu vas solliciter dans toute leur amplitude à un tempo doux. Deux ou trois minutes suffisent pour une courte session ; les sessions plus longues et les jours froids méritent plus.","Donne au bloc de pratique un seul focus. Choisis un mouvement que tu travailles et entoure-le de mouvements qui s'y enchaînent. Le builder montre comment chaque étape se connecte à la précédente : enchaînement direct depuis la même position de main, un petit re-grip, poser l'agrès, ou construire sur une figure précédente. Les routines qui coulent ressemblent à une danse ; les routines pleines de poses ressemblent à une liste.","Garde les changements de tempo petits entre les étapes. Passer de 80 à 130 BPM réinitialise ton timing et invite les chutes. Le co-pilote signale les sauts de plus d'environ un quart, en repliant le half et le double time pour qu'une étape de hoop à 70 BPM puisse côtoyer un morceau à 140 BPM.","Reviens au mouvement focus plus d'une fois. La répétition au fil d'une session, avec d'autres mouvements entre les deux, développe la compétence mieux qu'un seul long bloc, parce que chaque retour est une tentative fraîche depuis un point de départ légèrement différent.","Termine par un retour au calme : un mouvement facile à tempo lent, ou un court repos avec quelques respirations. Ça fait redescendre le rythme cardiaque et donne à ta coordination une fin paisible à mémoriser. Prévisualise la routine avant de la jouer et retire tout ce qui est clairement l'ambition d'hier."]},"effort":{"title":"Quand pousser le tempo","summary":"Pousse quand la forme tient et que tu es frais ; relâche quand les peaks vacillent, que la prise se crispe ou que les chutes commencent à s'accumuler.","imageAlt":"Figure 3D jonglant cinq balles en cascade haute","body":["Le progrès en flow vient de la pratique à la limite de tes capacités, mais la limite bouge. Certains jours elle est plus loin que prévu ; d'autres jours elle a reculé. Apprendre à la lire est une compétence qui vaut autant que n'importe quelle figure.","Pousse quand les bases tiennent. Si tes peaks sont réguliers, que ton staff reste dans son plan, que ton hoop reste à niveau et que ta respiration est facile, monte d'un échelon sur l'échelle de tempo ou essaie le drill suivant dans la progression. Les quinze premières minutes d'une session, après l'échauffement, sont généralement le meilleur moment pour du nouveau matériel.","Relâche quand la qualité baisse. Des chutes groupées, une prise qui se crispe, des épaules qui remontent vers les oreilles et une respiration retenue disent tous que ton système nerveux est fatigué. Baisse le tempo, reviens à un mouvement que tu maîtrises, ou termine la session. Pousser à travers la fatigue ne fait surtout que répéter les erreurs.","Surveille aussi les signaux physiques. Les lancers et les rotations répétitifs sollicitent les poignets, les avant-bras et les épaules. Une courbature qui disparaît en un jour est une adaptation normale. Une douleur vive, une douleur qui augmente pendant la pratique, un engourdissement ou des picotements sont des raisons de s'arrêter et de se reposer ; des symptômes persistants méritent un clinicien.","Utilise la note d'effort après chaque session. Le practice wizard la lit : plusieurs sessions difficiles d'affilée et il suggère quelque chose de plus doux, plusieurs faciles et il suggère un peu plus. Des notes honnêtes font de meilleures suggestions."]},"drops-are-data":{"title":"Les chutes sont des données","summary":"Une chute te dit quel lancer ou quelle réception corriger ; la traiter comme un échec ne t'apprend qu'à te crisper.","imageAlt":"Figure 3D échangeant deux balles de jonglage entre les mains","body":["Chaque jongleur a un jour un sol couvert de balles. Chaque spinner de staff a entendu le fracas. La différence entre les gens qui continuent de progresser et ceux qui arrêtent est rarement le talent ; c'est la façon dont ils traitent la chute.","Une chute est une mesure. Elle te dit quel lancer a mal tourné, quelle réception tu as cherchée, quel moment du spin a perdu son plan. Si la même balle retombe toujours devant toi, tes lancers dérivent vers l'avant. Si les chutes arrivent après six lancers, quelque chose dans ton troisième ou quatrième lancer ne va pas. Regarde où et quand, puis choisis une chose à changer.","Traiter les chutes comme un échec a un coût. La peur crispe les épaules et raccourcit la respiration, et la tension rend les mouvements plus petits et plus rapides, ce qui cause plus de chutes. La réponse calme — ramasser, respirer, attendre le temps fort, repartir — n'est pas seulement agréable ; c'est la réponse techniquement correcte.","Compte les runs propres, pas les chutes. SynthFlow valide un mouvement quand tu as assez de runs propres et de minutes de pratique, donc les chutes en chemin font simplement partie des minutes. Certains jours tu enregistreras dix runs propres, d'autres deux. Les deux jours comptent.","Fais tomber exprès parfois. Quand tu apprends une nouvelle figure, travaille le premier lancer ou le premier demi-spin et laisse tomber. Puis ajoute la réception. Isoler le moment risqué le réduit, et tu apprends que le sol n'est pas ton ennemi. C'est juste là où va l'agrès quand tu apprends."]},"safety":{"title":"Sécurité : espace, agrès et signaux d'alerte","summary":"Dégage tes plans, choisis des agrès indulgents, échauffe-toi, et arrête-toi en cas de douleur vive, d'engourdissement ou de vertige.","imageAlt":"Figure 3D faisant tourner un staff à plat au-dessus de la tête avec de l'espace dégagé autour","body":["Les flow arts présentent peu de risques comparés à la plupart des sports, mais les agrès vont vite et voyagent plus loin que prévu. Quelques habitudes gardent la pratique sûre pour toi, les personnes proches et le mobilier.","Dégage ton espace avant de commencer. Vérifie chaque plan que tu vas utiliser : devant, sur les côtés et au-dessus. Le staff et le hoop ont besoin de plus de place que tu ne le penses, généralement un cercle d'au moins l'envergure plus la longueur de l'agrès dans chaque direction, sans rien de cassable à portée. À l'intérieur, attention aux luminaires et aux ventilateurs ; dehors, attention au sol irrégulier et aux passants.","Utilise des agrès indulgents pendant l'apprentissage. Les balles de jonglage en beanbag ne roulent pas loin. Les staffs rembourrés ou à embouts en mousse font moins mal quand ils touchent ta tête, ce qui arrivera. Un hoop plus grand et plus lourd tourne plus lentement et est plus facile à maintenir. Passe à des agrès plus rapides ou plus flashy une fois les bases automatiques.","Échauffe-toi avant chaque session et augmente le volume progressivement. Lancer et faire tourner sont répétitifs, et la charge répétitive sur des tissus froids est la cause habituelle des poignets et coudes douloureux. Si tu ajoutes beaucoup de pratique d'un coup, ajoute aussi des jours de repos.","Arrête-toi en cas de signaux d'alerte : douleur vive ou électrique, engourdissement ou picotements dans les mains, douleur qui s'aggrave en continuant, vertige, ou un coup à la tête avec des symptômes persistants. Les mouvements de nuque et les contact rolls méritent une attention particulière ; apprends-les lentement avec un agrès rembourré.","Cette app enseigne la technique, pas les soins médicaux. Grossesse, blessures récentes, problèmes articulaires et tout ce qui t'inquiète sont des raisons de consulter un professionnel qualifié avant d'ajouter de la charge. La performance avec feu est une discipline à part avec sa propre formation sécurité ; SynthFlow ne l'enseigne pas."]},"warm-up":{"title":"Pourquoi l'échauffement compte pour le travail des agrès","summary":"Deux à cinq minutes de mobilité des poignets, bras, épaules et hanches rendent les rotations plus fluides et préservent tes articulations.","imageAlt":"Silhouette 3D faisant des cercles lents des poignets, bras tendus devant","body":["La pratique du flow paraît douce, mais elle sollicite beaucoup quelques articulations. La jonglerie répète le même lancer des milliers de fois ; le staff fait rouler les poignets sur toute leur amplitude ; le hoop balance la colonne et les hanches à chaque orbite. Un tissu chaud tolère bien mieux cette répétition qu'un tissu froid.","Un bon échauffement flow est court et spécifique. Les cercles de poignets dans les deux sens préparent les articulations qui font la majorité du travail. Les cercles de bras et les rotations d'épaules réveillent la coiffe des rotateurs et les omoplates, qui contrôlent le plan de chaque rotation. Les cercles de hanches et les torsions du buste comptent surtout pour le hoop. Les demi-cercles de nuque, jamais les rotations complètes, relâchent la tension liée au fait de regarder un pattern vers le haut.","Bouge lentement et en rythme. Les étapes d'échauffement dans SynthFlow sont comptées comme tout le reste, à un tempo détendu, pour que les premières minutes d'une session accordent aussi ton timing. Quand les agrès arrivent, tu bouges déjà avec la musique.","Termine l'échauffement avec l'agrès à moitié vitesse. Quelques lancers lents, un front spin tranquille ou une grande orbite de hoop lente relient le travail de mobilité au mouvement que tu vas travailler, et ils te disent comment ton corps se sent aujourd'hui.","L'échauffement est aussi une transition mentale. Les mêmes trois minutes au début de chaque session deviennent un signal que la pratique a commencé. Les jours chargés, l'échauffement est parfois toute la pratique, et ça compte quand même."]},"anatomy-basics":{"title":"Le corps derrière les agrès","summary":"Les avant-bras serrent et relâchent, les épaules dirigent le plan, le centre te garde stable : une carte simple pour le flow.","imageAlt":"Silhouette 3D faisant du hoop à la taille, haut du corps relâché","body":["Pas besoin de connaître l'anatomie pour jongler, mais une carte simple t'aide à comprendre ce qui fatigue, quoi échauffer et quoi reposer. La section Muscles de Learn a un modèle interactif ; cet article est la visite rapide.","Les avant-bras font la plupart du travail fin. Les muscles côté paume ferment les doigts et fléchissent le poignet ; les muscles du dos de l'avant-bras ouvrent les doigts et étendent le poignet. Attraper et relâcher, tenir un staff et le laisser rouler, tout se passe ici. La fatigue des avant-bras est la sensation la plus courante après une longue session, et c'est pourquoi la prise relâchée est un rappel si fréquent.","Les épaules dirigent. Les deltoïdes lèvent les bras ; la coiffe des rotateurs, quatre petits muscles autour de l'articulation, garde le haut du bras centré pendant qu'il bouge. Les muscles autour des omoplates maintiennent tout le système stable. Quand un staff dérive hors de son plan, la cause est souvent l'épaule, pas la main.","Le centre te garde tranquille. En jonglerie, un buste immobile empêche le pattern de dériver. En hoop, les muscles abdominaux et du dos entraînent le hoop avec de petites impulsions avant-arrière. Les hanches et les jambes sont ta base : des genoux souples absorbent le mouvement et te laissent déplacer ton poids sans perturber l'agrès.","Tes yeux et ton oreille interne comptent aussi. La jonglerie t'entraîne à regarder les sommets, pas les mains ; le spin entraîne ton équilibre. Des sessions courtes avec des pauses laissent les deux s'adapter sans vertiges. Prends cette carte comme un savoir de base, pas un diagnostic, et consulte un professionnel pour une douleur qui ne passe pas."]},"biomechanics-safety":{"title":"Poignets, épaules et charge répétitive","summary":"Prise relâchée, poignets neutres et volume progressif gardent heureuses les articulations qui font tout le travail.","imageAlt":"Silhouette 3D faisant tourner un staff d'une main sur le dos de la main","body":["Les blessures en flow sont rarement spectaculaires. Ce sont presque toujours des surcharges : trop de répétitions, trop de prise, trop peu de repos. La bonne nouvelle, c'est que les mêmes quelques habitudes évitent la plupart d'entre elles.","Relâche la prise. Une balle de jonglerie n'a besoin que de juste assez de pression pour rester dans la main ; un staff a besoin d'un anneau de doigts lâche dans lequel il peut rouler. Serrer fatigue les muscles de l'avant-bras et charge les tendons au coude. Si tes jointures blanchissent ou que tes avant-bras brûlent après quelques minutes, relâche et baisse le tempo.","Garde les poignets proches du neutre quand tu peux. Le spin fait passer les poignets sur de grandes amplitudes, ce qui est très bien avec modération. Les tenir en fin d'amplitude longtemps, ou forcer un poignet raide à tourner, voilà ce qui les irrite. Laisse le coude et l'épaule partager le mouvement.","Laisse les épaules travailler, mais sans les hausser. Les grands cercles viennent de l'articulation de l'épaule ; une épaule haussée pince et fatigue vite. Vérifie dans le miroir ou le mode caméra que tes épaules restent basses, surtout dans les mouvements au-dessus de la tête comme l'hélicoptère et le lasso.","Augmente le volume progressivement. Si tu pratiques vingt minutes d'habitude, ne passe pas à deux heures parce qu'un festival arrive. Augmente le temps total d'une quantité modeste chaque semaine et garde au moins un jour facile. Alterne les agrès pour répartir la charge : le hoop repose les avant-bras que la jonglerie fatigue.","Une douleur qui disparaît en un jour est une adaptation normale ; une douleur qui persiste, s'aggrave ou s'accompagne d'engourdissement ne l'est pas. Repose-toi, réduis le volume et demande un avis professionnel si ça persiste. Ceci est éducatif, pas un avis médical."]},"choosing-props":{"title":"Choisir ses premiers agrès","summary":"Des beanbags pour la jonglerie, un staff léger rembourré et un grand hoop adulte rendent les premières semaines bien plus faciles.","imageAlt":"Silhouette 3D faisant tourner un hoop autour d'une main","body":["De bons agrès de débutant rendent l'apprentissage plus rapide et moins frustrant. Pas besoin de matériel cher, mais quelques choix comptent.","Pour la jonglerie, commence avec trois beanbags d'environ 60 à 130 grammes chacun. Les beanbags ne rebondissent pas et ne roulent pas quand ils tombent, ce qui évite beaucoup de courses. Ils doivent tenir confortablement dans ta paume. Les stage balls, plus grosses, et les balles en silicone rebondissantes, c'est pour plus tard. Des couleurs assorties t'aident à voir le pattern ; trois couleurs différentes t'aident à suivre chaque balle quand tu apprends les siteswaps.","Pour le staff, un staff de spin débutant mesure généralement autour de 1,2 à 1,5 mètre, léger, avec des embouts rembourrés ou en caoutchouc. En gros, il devrait arriver entre ta poitrine et ton épaule posé debout. Un staff plus long et plus lourd tourne plus lentement et plus doucement une fois les bases acquises, mais il est plus dur pour commencer et fait plus mal quand il te touche. Une prise au milieu aide.","Pour le hoop, commence plus grand et plus lourd que tu ne le penses. Un hoop adulte débutant arrive généralement entre la taille et la poitrine posé au sol. Les grands hoops tournent plus lentement, te donnant le temps de trouver le rythme pour le waist hooping. Les hoops plus petits et plus légers conviennent aux tricks rapides hors du corps une fois à l'aise.","Quoi que tu choisisses, assure-toi que la plage de tempo du mouvement convient à l'agrès. Les agrès plus lourds aiment généralement les tempos plus bas. Si la plage confortable de l'app te semble précipitée avec ton agrès, règle ton propre tempo dans le builder ; les comptes suivent."]},"practice-at-home":{"title":"Pratiquer à la maison et au parc","summary":"Des sessions quotidiennes courtes, un espace dégagé, un bord de lit ou de canapé pour rattraper les chutes, et un jam au parc quand tu peux.","imageAlt":"Silhouette 3D secouant les bras entre les rounds de pratique","body":["La plupart des flow artists apprennent à la maison, quelques minutes à la fois. Un petit aménagement rend la pratique à la maison plus facile à commencer et à tenir.","Trouve ton coin. Pour la jonglerie, te tenir devant un lit ou un canapé fait que les balles tombées atterrissent à hauteur de taille au lieu de rouler sous les meubles, et ça t'empêche aussi d'avancer. Pour le staff et le hoop, trouve le plus grand espace dégagé que tu as, vérifie le plafond et range tout ce qui est fragile. Un jardin ou un parc est mieux pour les grandes rotations.","Garde les agrès visibles. Des balles sur le bureau se jonglent pendant les appels et les pauses thé ; un hoop près de la porte sert. Moins il faut d'effort pour commencer, plus souvent tu le feras. Une routine de cinq minutes compte, et plusieurs sessions courtes par jour s'additionnent vite.","Utilise l'appli comme structure. Choisis une routine ou laisse l'assistant t'en suggérer une, joue-la en entier et note ton effort. Les programmes courts comme Zero to Cascade donnent un objectif clair à chaque semaine, ce qui t'évite de dériver entre les figures.","Entraîne-toi avec d'autres quand tu peux. Les clubs de jonglage, les écoles de cirque et les jams de flow en plein air existent dans beaucoup de villes. Regarder quelqu'un qui a un pas d'avance sur toi corrige souvent ce qu'un tutoriel n'a pas pu, et enseigner à quelqu'un qui a un pas de retard rend ta propre technique plus claire. Apporte tes agrès, demande aux gens ce qu'ils travaillent et partage ce que les comptes t'ont appris."]},"learning-with-the-app":{"title":"Apprendre avec le coach 3D","summary":"Ralentis, mets en miroir, active le ghost et les trails, change la caméra et utilise le mode caméra pour avoir un retour.","imageAlt":"Figure 3D exécutant une isolation au staff avec un trail montrant la trajectoire","body":["Chaque mouvement dans SynthFlow est animé en 3D sur la même horloge que la musique, donc la figure est toujours exactement sur le beat. Bien utilisé, le viewer est un professeur patient qui ne se lasse jamais de te montrer le même lancer.","Ralentis d'abord. L'échelle de progression de chaque mouvement commence par des versions lentes et partielles, puis mains seules, puis le mouvement complet sur le beat. La demi-vitesse garde les relations de timing intactes tout en donnant à tes yeux le temps de suivre.","Mets la figure en miroir si tu apprends mieux face à un professeur, et change la caméra quand une vue cache quelque chose. Les vues de côté montrent l'inclinaison du staff et la dérive des lancers ; les vues du dessus montrent les plans du hoop et les trajectoires d'hélicoptère. Les trails dessinent où chaque agrès est passé, ce qui transforme un flou en une forme que tu peux étudier. Le ghost montre où l'agrès sera sur le beat suivant.","Observe les erreurs courantes. Chaque mouvement peut montrer ses défauts typiques, comme dériver vers l'avant, des hauteurs inégales ou précipiter, joués volontairement mal sur la figure, avec l'indice qui les corrige. Reconnaître un défaut sur le modèle rend beaucoup plus facile de le ressentir dans ton propre corps.","Le mode caméra te donne un retour sur toi. Avec ton accord, il suit tes mains et ton corps pendant que tu t'entraînes et compare ton timing avec le beat. Le traitement se fait sur ton appareil. Ce n'est pas parfait, et un bon éclairage aide, mais même un retour approximatif sur le fait que tu sois en avance ou en retard est précieux.","Enfin, ferme parfois le viewer. Entraîne-toi avec la musique seule et fais confiance aux comptes. L'objectif est un mouvement que tu peux faire sans rien regarder du tout."]},"music-for-flow":{"title":"Trouver une musique qui colle","summary":"Des tempos mesurés, la demi et le double tempo, des percussions générées et tes propres morceaux gardent les comptes honnêtes.","imageAlt":"Figure 3D faisant du hoop à la poitrine avec les bras levés","body":["La musique transforme la pratique en flow, mais seulement si le beat de la musique est le beat des comptes. Un morceau à 118 BPM sous une routine à 120 BPM se décale en moins d'une minute, et tu finis par te battre contre la musique au lieu de la chevaucher.","Les morceaux inclus dans SynthFlow ont des tempos et des downbeats mesurés, donc le lecteur peut commencer chaque étape sur le « un » de la musique et garder les comptes alignés. Le builder liste d'abord les morceaux qui correspondent au tempo d'une section, y compris les morceaux à la moitié ou au double du tempo : un morceau à 140 BPM porte parfaitement bien une étape de hoop à 70 BPM.","Les percussions générées fonctionnent à n'importe quel tempo. Choisis un kit pour une section et le lecteur synthétise un beat qui correspond exactement, que tu fasses une échelle de tempo ou un drill lent. C'est aussi la meilleure option quand tu veux la pulsation sans qu'une mélodie attire ton attention.","Tu peux analyser des morceaux depuis ton propre appareil. L'appli estime le tempo et le downbeat et te laisse les vérifier en tapant en rythme. Les morceaux avec une pulsation électronique ou acoustique régulière fonctionnent le mieux ; la musique avec des changements de tempo, du rubato ou de longues intros est plus difficile à mesurer et plus difficile pour s'entraîner.","Le streaming vidéo est désactivé pendant la pratique comptée car son timing ne peut pas être contrôlé précisément. Utilise-le plutôt pour les échauffements ou le free play, là où rien n'a besoin de s'aligner."]},"plateaus":{"title":"Les plateaux et le long milieu","summary":"Chaque flow artist passe par des semaines où rien ne progresse ; change le drill, le tempo ou l'agrès avant de changer l'objectif.","imageAlt":"Figure 3D jonglant le Mills Mess avec les bras croisés","body":["Le début du flow est merveilleux : quelque chose de nouveau à chaque session. Puis, souvent vers le moment où tu sais jongler une cascade régulière ou garder un hoop en l'air indéfiniment, la progression semble s'arrêter. C'est dans ce long milieu que la plupart des gens abandonnent, et que l'apprentissage le plus intéressant se produit.","Les plateaux sont généralement de la consolidation. Ton système nerveux réorganise le mouvement pour qu'il demande moins d'attention, ce qui ne se voit pas sous forme de nouvelles figures. Souvent, une compétence qui semblait bloquée pendant deux semaines apparaît soudain un matin. Continue à pratiquer pendant la partie plate.","Change le drill, pas l'objectif. Si la cascade ne veut pas s'accélérer, travaille-la à un tempo plus bas avec des sommets parfaits, puis avec les yeux fixés sur un point au-dessus du pattern, puis avec une seule main. Si un mouvement de staff ne vient pas, découpe-le en deux moitiés et travaille chacune sur le beat. De nouveaux drills donnent à ton cerveau de nouvelles informations sur la même compétence.","Fais du cross-training. Apprendre un deuxième agrès débloque souvent le premier. Le hoop améliore le rythme derrière le jonglage ; le travail du staff enseigne les plans qui rendent les figures de hoop propres. L'arbre de Rewards de chaque art est indépendant, donc la variété ne coûte jamais de progression.","Sois bienveillant avec toi-même. Compare-toi au mois dernier, pas aux performeurs en ligne qui s'entraînent depuis dix ans. La page Progress garde une trace honnête des minutes, des tempos max et des mouvements maîtrisés. Une semaine plate, regarde-la et vois jusqu'où la ligne est déjà montée."]},"history-of-juggling":{"title":"Une brève histoire du jonglage","summary":"D'une peinture de tombe égyptienne aux jongleurs médiévaux, au théâtre de variétés et aux mathématiques modernes.","imageAlt":"Figure 3D jonglant une shower à trois balles en cercle","body":["Le jonglage est très ancien. L'une des plus anciennes images connues est une peinture murale dans une tombe du Moyen Empire à Beni Hasan en Égypte, vieille d'environ quatre mille ans, montrant des femmes lançant des balles. Des récits et des images de Chine, de Grèce, de Rome et du Pacifique suggèrent que des personnes de nombreuses cultures ont trouvé le chemin du lancer et de la rattrape pour le spectacle et le jeu.","Dans l'Europe médiévale, le mot jongleur, d'où vient « juggler », désignait des artistes itinérants qui chantaient, racontaient des histoires, faisaient des acrobaties et lançaient des objets. Le jonglage était une compétence parmi d'autres, faisant partie de la boîte à outils d'un performeur plutôt qu'un art à part entière.","Les théâtres de variétés et les cirques des XIXe et début XXe siècles ont fait du jonglage un numéro de tête d'affiche. Les performeurs se sont spécialisés : jongleurs gentlemen avec chapeaux et cannes, jongleurs de massues, et jongleurs de nombres poussant vers sept, huit balles et plus. Enrico Rastelli, au début du XXe siècle, est encore souvent cité comme l'un des plus grands.","À partir des années 1970, une culture du jonglage de loisir s'est développée autour de clubs, de festivals et de conventions, avec des gens partageant librement des figures. Les mathématiques s'y sont jointes dans les années 1980 quand la notation siteswap a donné aux jongleurs un moyen d'écrire les patterns sous forme de nombres, menant à de nouvelles figures découvertes sur papier avant que quiconque ne les lance.","Aujourd'hui, le jonglage se situe au point de rencontre du cirque, du sport, de la danse et des maths. Certains jongleurs rivalisent sur les nombres et l'endurance, d'autres exécutent des chorégraphies sur musique, d'autres explorent des patterns pour eux-mêmes. Chaque voie commence par le même échange de deux balles, que tu peux apprendre cette semaine."]},"history-of-staff":{"title":"Le staff spinning : de l'arme au flow","summary":"Les bâtons d'arts martiaux, le twirling de baton et la performance avec le feu ont tous nourri le spin staff moderne.","imageAlt":"Figure 3D exécutant un butterfly au staff derrière les épaules","body":["Un staff est l'un des plus anciens outils qui existent, et en faire tourner un est une compétence ancienne. De nombreuses traditions martiales s'entraînent avec un long bâton, parmi elles le bō d'Okinawa, le gun chinois et le combat au quarterstaff européen, et leurs drills incluent des spins rapides et des changements de main pour la défense comme pour la démonstration.","Le spinning de performance a d'autres racines aussi. Le twirling de baton est devenu une discipline compétitive au XXe siècle, avec des lancers, des roulades et des spins que les spinners empruntent encore. Le théâtre, les parades et le spectacle de rue à travers le monde utilisaient des bâtons et des perches en rotation bien avant que quiconque n'appelle cela du flow.","La scène moderne du staff flow est née à la fin du XXe siècle, en parallèle du spectacle de feu et de la culture festivalière. Les staffs de feu, avec des mèches à chaque extrémité, rendaient la rotation visible dans l'obscurité et poussaient l'art vers un mouvement fluide et continu plutôt que vers des frappes. Les staffs LED ont ensuite apporté les mêmes visuels en intérieur.","À la même époque, les flow artists ont commencé à décrire la rotation avec une théorie partagée : les plans, le spin et l'antispin, les isolations, le timing et la direction. Une grande partie a été développée dans la communauté du poi puis transposée au staff, au hoop et à d'autres props, c'est pourquoi les mêmes mots apparaissent partout dans cette app.","Le contact staff, où le staff roule sur le corps au lieu d'être saisi, est devenu un style à part entière avec des rolls sur la nuque, les épaules et les bras. Aujourd'hui, le staff spinning va de la démonstration martiale au contact flow lent et méditatif, le tout construit sur le même premier wheel spin."]},"history-of-hoop":{"title":"Le hoop : du jouet ancien à l'art du flow","summary":"Les hoops sont des jouets et des outils depuis des millénaires ; une mode des années 1950 et un renouveau festivalier ont fait de la hoop dance un art.","imageAlt":"Silhouette 3D faisant monter un hoop en rotation le long du corps","body":["Les hoops comptent parmi les jouets les plus anciens. Des enfants de l'Égypte, de la Grèce et de la Rome antiques sont décrits ou représentés faisant rouler des hoops avec des bâtons et les faisant tourner autour du corps, et des jeux de hoop apparaissent dans de nombreuses cultures depuis.","Les hoops portent aussi une signification culturelle profonde dans certaines traditions. La Hoop Dance pratiquée dans de nombreuses communautés amérindiennes utilise plusieurs hoops pour former des figures comme des animaux et la terre, racontant des histoires par le mouvement. C'est une tradition vivante à part entière, distincte de la scène flow moderne, et qui mérite d'être découverte auprès de ses propres praticiens.","La mode du hula hoop en plastique à la fin des années 1950, portée par des hoops produits en masse aux États-Unis, a mis un hoop dans des millions de foyers presque du jour au lendemain. Pendant des décennies ensuite, le hoop a surtout été vu comme un jouet pour enfants et un gadget de fitness.","À partir de la fin des années 1990 et des années 2000, des hoopers adultes dans les festivals et les communautés en ligne ont commencé à traiter le hoop comme un partenaire de danse. Des hoops plus grands et plus lourds, faits main, ont rendu le on-body hooping plus facile pour les adultes, tandis que les hoops plus petits ouvraient des tricks off-body rapides. Les vidéos partagées ont diffusé un vocabulaire comme les isolations, les wedgies et les escalators bien au-delà d'une seule ville.","La hoop dance moderne emprunte la théorie au staff et au poi et le rythme à toutes sortes de musiques. Elle est accessible, joyeuse et profonde : un débutant peut trouver le rythme de taille en un jour, et un expert peut passer des années à affiner une seule isolation."]},"fire-and-led":{"title":"Props de feu, LED et de spectacle","summary":"Les props de spectacle changent le poids, la vitesse et le risque ; apprends chaque mouvement avec des props d'entraînement d'abord et travaille le feu séparément.","imageAlt":"Silhouette 3D faisant tourner un hoop à plat au-dessus de la tête comme un lasso","body":["Voir un staff de feu ou un hoop LED la nuit est souvent ce qui attire les gens vers le flow. Les props de spectacle sont merveilleux, mais ils ne sont pas identiques aux props d'entraînement, et passer à eux mérite un plan.","Les props LED sont généralement plus lourds que leurs versions d'entraînement à cause des batteries et de l'électronique. Cela change l'élan : les rotations portent plus loin, les lancers sont différents, et les poignets travaillent plus. Apprends chaque mouvement avec ton prop d'entraînement d'abord, puis attends-toi à une courte période d'adaptation en LED. Baisse le tempo pour les premières sessions.","Le spectacle de feu est une discipline à part. La manipulation du carburant, les zones de rotation sûres, les safety spotters avec couvertures anti-feu, des vêtements adaptés et les règles locales comptent, et il vaut mieux les apprendre en personne auprès de performers de feu expérimentés. SynthFlow n'enseigne pas le feu, et rien dans l'app ne doit être pratiqué avec des props allumés.","Une bonne règle utilisée dans de nombreuses communautés flow est de ne réaliser un mouvement avec un prop de spectacle qu'une fois qu'on peut le faire de manière fiable, plusieurs fois d'affilée, avec un prop d'entraînement. Sous les lumières ou les flammes, il n'y a pas de place pour les expérimentations.","Le spectacle change aussi ta façon d'enchaîner. Le public lit les grands plans, les transitions propres et les moments de stillness clairs. Construis tes routines de spectacle dans le builder comme n'importe quelle autre, prévisualise-les, et répète avec la même musique à chaque fois pour que les counts deviennent de la chorégraphie."]}}`),r=JSON.parse(`{"the-day-the-cascade-clicked":{"title":"Le jour où la cascade a cliqué","summary":"Trois semaines à courir après les balles à travers la pièce se sont terminées le moment où j'ai arrêté de regarder mes mains et commencé à compter.","body":["Pendant trois semaines, ma cascade à trois balles a duré exactement quatre lancers. Droite, gauche, droite, et puis la troisième balle était quelque part derrière le canapé. J'ai regardé des vidéos, j'ai ralenti, j'ai accéléré. Je me suis placé devant le lit comme tous les tutos le disent. Rien n'a changé, sauf mon vocabulaire.","La solution, quand elle est venue, était d'une simplicité gênante. J'ai mis un morceau à 90 BPM et j'ai dit les counts à voix haute : un, deux, trois, quatre, un lancer sur chaque temps. Soudain, les lancers avaient un endroit où aller. Au lieu de lancer quand la main se sentait prête, c'est-à-dire quand la panique le lui disait, chaque lancer attendait son temps. Le pattern est devenu plus lent, plus haut et plus calme.","La deuxième solution était où je regardais. Je fixais mes mains, ce qui revient à lire un livre en regardant ses paupières. Quand j'ai levé le regard vers les peaks, les deux points au sommet des arcs, mes mains ont commencé à rattraper toutes seules. Les peaks me disaient si les lancers étaient réguliers ; les mains n'avaient pas besoin de surveillance.","Douze lancers sont devenus vingt, puis cinquante. Un soir, j'ai jonglé pendant tout un step de huit mesures sans drop et j'ai souri au plafond comme un idiot. L'app a appelé ça un clean run. Moi, j'ai appelé ça la première fois que la jongle ressemblait à de la musique plutôt qu'à un combat.","Si tu es bloqué à quatre lancers, essaie ce qui a marché pour moi : compte à voix haute, lance sur le temps, regarde les peaks. Et drop sans drama. Le sol, c'est là où commence toute cascade."]},"why-we-count-in-bars":{"title":"Pourquoi on compte en mesures, pas en secondes","summary":"Une tenue de quarante secondes a du sens pour un étirement ; un pattern de jongle vit sur un temps, alors on mesure la pratique en mesures.","body":["Quand on a commencé à construire SynthFlow, la première grande décision a été comment mesurer un step de routine. Notre app sœur SynthYoga compte les tenues en secondes et en respirations. Ça marche pour une pose que tu tiens. Ça ne marche pas pour un pattern qui se répète sur un temps.","Un lancer de jongle, un demi-tour de staff et une orbite de hoop sont tous des cycles. Si la musique tourne à 100 BPM et que ta cascade tourne à 103, tu ne jongles pas sur la musique ; tu jongles à côté, et en une minute tu es un temps en retard. Mesurer les steps en mesures à un tempo signifie que la musique, les counts, la silhouette 3D et le step suivant démarrent tous sur le même downbeat.","Les mesures rendent aussi le progrès concret. « Jongle pendant une minute » est vague : une minute de quoi, à quelle vitesse ? « Huit mesures de cascade à 96 BPM » est un défi précis et reproductible. Si tu y arrives proprement, la session suivante peut demander 104. C'est comme ça que fonctionnent les échelles de tempo, et pourquoi la maîtrise dans l'app dépend de clean runs plutôt que du simple temps.","Ça a demandé une vraie ingénierie. Chaque animation est pilotée par la même horloge audio que la musique, planifiée à l'avance pour que rien ne saccade. Les morceaux intégrés ont des tempos et des downbeats mesurés. Les percussions générées remplissent n'importe quel tempo que tu choisis. Les morceaux de ton appareil sont analysés et vérifiés avec un tap test. La vidéo en streaming est désactivée en pratique comptée parce qu'on ne peut pas la garder sur le temps.","Le résultat, c'est que le beat devient un professeur. Quand tu dérives, tu l'entends. Quand tu te cales, tu le sens. Compter en mesures s'est révélé être le choix de design le plus important qu'on ait fait."]},"staff-hit-me-in-the-head":{"title":"Le staff m'a frappé à la tête (et autres leçons)","summary":"Chaque staff spinner se fait bonker ; le padding, les plans et la patience transforment les bonks en progrès.","body":["Mon premier figure-8 s'est terminé avec le staff qui rebondissait sur mon crâne et le chien qui quittait la pièce. Mon deuxième s'est terminé pareil, sans le chien. Si tu apprends le staff, tu te feras frapper. La question, c'est à quel point fort, et ce que tu en apprends.","Leçon un : le padding n'est pas de la lâcheté. Un staff d'entraînement avec des embouts souples a transformé les bonks de cris en haussements d'épaules. Le haussement d'épaules compte, parce que la peur fait flincher, et un poignet qui flinche tire le staff hors de son plan, ce qui cause le bonk suivant.","Leçon deux : la plupart des coups viennent de plans inclinés. Quand je me suis filmé de côté, je pouvais voir le staff pencher vers mon visage au sommet de chaque tour. Mes poignets roulaient vers l'intérieur. L'overlay de plan dans la visionneuse 3D montrait la version propre : le staff dans une feuille plate à côté du corps, sans jamais pencher vers l'intérieur. Corriger le poignet a corrigé les bonks.","Leçon trois : lent et compté bat rapide et plein d'espoir. J'ai baissé le tempo au bas de la plage du figure-8 et j'ai compté « côté droit, côté gauche » avec la musique. À cette vitesse, je pouvais sentir le changement de main et garder le plan plat. Une semaine plus tard, je pouvais remonter.","Leçon quatre : ris. Le staff spinning est ridicule et merveilleux. Les bonks font partie de l'histoire que tout le monde dans la scène partage. Mets un chapeau si besoin, dégage les lumières du plafond, et continue à spinner."]},"hooping-for-people-who-cant-hoop":{"title":"Le hooping pour ceux qui pensent ne pas savoir hooper","summary":"La plupart des adultes qui « ne savent pas hooper » ont essayé avec un hoop de la taille d'un jouet ; un hoop plus grand et une impulsion avant-arrière règlent la plupart du temps le problème.","body":["« Je ne sais pas hooper » est une phrase que les profs de hoop entendent constamment, généralement de quelqu'un qui a essayé pour la dernière fois avec un hoop de jouet pour enfant. Les hoops petits et légers tournent vite et tombent vite. Ils exigent des hanches rapides et frénétiques. Les adultes avec un hoop de taille adulte trouvent souvent cela bien plus gérable.","Commencez grand. Un hoop qui atteint à peu près entre votre taille et votre poitrine posé au sol tourne assez lentement pour que vous sentiez le rythme. Les hoops plus lourds portent aussi plus d'élan. Vous pourrez passer à plus petit plus tard pour la vitesse et les tricks off-body.","Pulsez, ne faites pas de cercles. L'erreur la plus courante est d'essayer de faire de grands cercles avec les hanches. Le waist hooping est généralement un petit balancement avant-arrière, ou latéral, en rythme avec le hoop. Un pied légèrement en avant aide. Le hoop touche votre ventre et votre dos ; vous poussez doucement quand il passe.","Comptez. Un tempo détendu, une orbite par temps, donne à votre corps un rythme dans lequel s'installer. L'app commence le waist hooping lentement, puis vous laisse monter. Si le hoop descend, ajoutez un peu de vitesse à votre impulsion, pas un mouvement plus grand.","Attendez-vous à ce qu'il tombe beaucoup pendant quelques sessions, puis soudainement plus. Le hooping est l'une de ces compétences qui fait tilt. Une fois que c'est le cas, tout un monde de flow on-body et off-body vous attend, et une bonne partie n'a même pas besoin de la taille."]},"unlocking-is-not-a-race":{"title":"Débloquer n'est pas une course","summary":"L'arbre des récompenses ouvre des mouvements plus difficiles à mesure que vous maîtrisez leurs fondations ; l'essentiel, ce sont les fondations.","body":["Les récompenses de SynthFlow sont des mouvements. Maîtrisez la cascade et la reverse cascade s'ouvre ; maîtrisez le front spin et le figure-8 apparaît. C'est satisfaisant de voir l'arbre s'illuminer, et nous l'avons conçu pour ça. Mais il y a un piège dans tout système de déblocage, et ça vaut la peine de le nommer.","Le piège, c'est de traiter la maîtrise comme une case à cocher. Vous pouvez techniquement enregistrer les runs propres d'un mouvement un bon jour, débloquer le suivant, et passer à autre chose avec une fondation qui ne fonctionne que quand tout va bien. Ensuite, les mouvements plus difficiles semblent impossibles, parce qu'ils supposent que la fondation tient quand ça va mal.","La maîtrise en flow, c'est quand le mouvement survit à la distraction : un peu de fatigue, un tempo différent, quelqu'un qui passe. C'est pourquoi la maîtrise demande des runs propres sur plusieurs sessions, pas seulement une. Et c'est pourquoi nous suggérons de revenir régulièrement aux mouvements maîtrisés. La cascade n'est pas un niveau que l'on termine ; c'est le sol sur lequel tout l'arbre du jonglage repose.","Les mouvements verrouillés ont quand même des pages. Vous pouvez les lire, les regarder en 3D et voir ce qu'ils demandent. Regarder devant est motivant. Pratiquer devant, sans les fondations, est surtout frustrant.","Alors profitez des déblocages, mais mesurez-vous à la facilité de vos plus anciens mouvements. Quand la cascade est ennuyeuse, vous êtes prêt pour le Mills Mess. Quand le Mills Mess est ennuyeux, l'arbre a plus à offrir."]},"practice-in-ten-minutes":{"title":"Une vraie pratique en dix minutes","summary":"Échauffement, un mouvement focus, un lien, une petite montée de tempo et un retour au calme : dix minutes, chaque jour.","body":["La raison la plus courante que les gens donnent pour ne pas pratiquer, c'est le temps. La vérité, c'est que les compétences de flow répondent brillamment à des sessions courtes et fréquentes. Voici la forme en dix minutes que nous utilisons nous-mêmes.","Minutes une à deux : échauffement. Cercles de poignets, cercles de bras, rotations d'épaules, quelques cercles de hanches si vous faites du hoop. Comptés, à un tempo détendu, pour que votre timing se réveille avec vos articulations.","Minutes trois à cinq : votre mouvement focus. Un mouvement sur lequel vous travaillez, à un tempo que vous pouvez tenir proprement. Plusieurs courts passages comptés plutôt qu'un long, avec une respiration entre eux.","Minutes six à sept : un lien. Associez le mouvement focus à quelque chose dans lequel il s'enchaîne ou d'où il vient. Cascade vers reverse cascade. Front spin vers figure-8. Waist vers chest. Les liens sont ce qui fait qu'une pratique ressemble à du flow plutôt qu'à des drills.","Minutes huit à neuf : une petite montée de tempo. Deux ou trois paliers, quelques BPM chacun, en s'arrêtant avant que la forme casse. Terminez sur un palier propre.","Minute dix : retour au calme. Un mouvement lent et facile ou un court repos. Enregistrez votre effort. Terminé.","Dix minutes par jour, c'est plus d'une heure par semaine de pratique concentrée, répartie de la façon que la coordination préfère. Le practice wizard construit des sessions de cette taille quand vous lui dites que vous manquez de temps, et les routines courtes intégrées suivent la même forme."]},"antispin-broke-my-brain":{"title":"L'antispin m'a cassé le cerveau (pendant une semaine)","summary":"Tourner le staff contre le cercle de la main semble impossible jusqu'à ce que les comptes donnent à chaque pétale un temps.","body":["L'antispin, c'est là où le staff spinning commence à ressembler à un devoir de géométrie. Votre main dessine un cercle dans un sens pendant que le staff tourne dans l'autre, et les extrémités tracent une fleur. La première fois que j'ai essayé, j'ai produit quelque chose qui ressemblait plus à un pissenlit fané.","Ce qui a aidé, c'est de rendre la forme comptable. Un antispin à quatre pétales a quatre moments où une extrémité pointe droit vers l'extérieur du cercle. J'ai donné à chacun un temps : haut, côté, bas, côté. Puis j'ai ralenti la musique bien en dessous de mon tempo habituel et j'ai simplement visé les positions sur les temps.","Le ghost dans la visionneuse 3D, qui montre où le staff devrait être au temps suivant, a été mon meilleur ami cette semaine-là. Tout comme la traînée, qui dessinait ma fleur pour que je voie quand les pétales étaient inégaux. En général, le pétale du bas était écrasé, parce que je précipitais le bas du cercle.","Après environ une semaine, quelque chose a basculé. J'ai arrêté de penser à la main et au staff comme deux choses et j'ai commencé à sentir la fleur comme une seule forme. Le tempo est revenu tout seul.","Si l'antispin vous casse le cerveau, c'est normal. Donnez à chaque pétale un temps, ralentissez la musique, et laissez votre corps trouver la solution. C'est l'une des meilleures sensations en flow quand ça arrive."]},"siteswaps-for-the-maths-shy":{"title":"Les siteswaps pour ceux qui n'aiment pas les maths","summary":"Vous n'avez pas besoin d'aimer les maths pour utiliser les siteswaps ; vous avez seulement besoin de savoir que les grands chiffres vont plus haut.","body":["La notation siteswap a une réputation qui fait fuir les gens. Les jongleurs diront joyeusement « essaie 531 » comme si ça expliquait quelque chose. C'est le cas, mais seulement une fois que vous savez deux ou trois choses, et ces choses sont plus simples qu'elles en ont l'air.","Voici presque tout ce dont vous avez besoin. Chaque chiffre est un lancer. Les grands chiffres vont plus haut. Les chiffres impairs croisent vers l'autre main ; les chiffres pairs reviennent dans la même main. Un 3 est un lancer de cascade normal. Un 1 est un zip rapide vers l'autre main. Un 2, c'est généralement juste tenir la balle.","C'est assez pour lire 441 : deux lancers plus hauts qui restent de leur côté, puis un zip vers l'autre main. Vous pouvez maintenant l'essayer sans lire un mot de plus. Lancer, lancer, zip, sur le temps.","Si vous voulez une pièce de plus : additionnez les chiffres et divisez par leur nombre, et vous obtenez le nombre de balles. 4 + 4 + 1 = 9, divisé par 3 donne 3 balles. Si la réponse n'est pas un nombre entier, le pattern ne peut pas être jonglé. C'est tout le fameux théorème de la moyenne.","Dans SynthFlow, chaque mouvement de jonglage a un siteswap, et le moteur 3D s'anime directement à partir de lui. Cela signifie que la figure lance toujours exactement les hauteurs que les chiffres décrivent, sur les temps exacts. Regarder un siteswap animé lentement est le moyen le plus rapide que nous connaissions pour que les chiffres aient du sens. Aucun diplôme de maths requis."]},"music-that-fights-you":{"title":"Quand la musique vous combat","summary":"Un morceau qui dérive par rapport aux comptes rend chaque mouvement plus difficile ; des tempos mesurés et des beats générés règlent ça.","body":["Vous l'avez probablement ressenti : une chanson que vous aimez, un mouvement que vous connaissez, et pourtant tout semble faux. Vous précipitez, vous faites tomber, vous vous blâmez. Souvent, le problème n'est pas vous. C'est que le tempo de la chanson ne correspond pas au mouvement.","Chaque mouvement de flow a une plage de tempo confortable. En dessous, les props s'arrêtent ; au-dessus, les lancers deviennent bas et frénétiques. Un morceau à 128 BPM sous un mouvement de hoop qui aime 90 vous demande de choisir entre la musique et le hoop. La bonne nouvelle, c'est que la half time et la double time aident : 128 peut porter un mouvement à 64, un cycle toutes les deux temps.","Le drift est le problème plus subtil. Si la musique dit 120 mais que les counts disent 116, les deux glissent l'un par rapport à l'autre en une minute, et votre corps ne peut pas suivre les deux. C'est pourquoi SynthFlow utilise des tempos mesurés pour ses morceaux intégrés, génère des percussions à n'importe quel tempo exact, et vérifie les morceaux de votre appareil avec un tap test.","Quand un morceau vous résiste, ne résistez pas. Passez au beat généré pour l'étape, ou laissez le builder suggérer un morceau dans la bonne plage. Gardez les chansons que vous aimez pour le free play, là où rien n'a besoin de s'aligner.","La musique doit se sentir comme un partenaire. Si elle se sent comme un adversaire, changez la musique, pas votre mouvement."]},"learning-alongside-my-kid":{"title":"Apprendre à jongler avec mon enfant","summary":"Deux débutants, un sac de balles et une règle : on célèbre les chutes aussi fort que les catches.","body":["Ma fille a demandé à apprendre la jonglerie, et j'ai réalisé que je ne savais pas jongler non plus. Alors on a appris ensemble, dix minutes après le dîner, avec trois beanbags chacun et une règle : on acclame les chutes aussi fort que les catches.","La règle semble ridicule. Elle s'est avérée être la partie la plus importante. Les enfants, et les adultes, se crispent quand ils pensent qu'une erreur est embarrassante. La tension rend les lancers pires. Acclamer chaque chute a transformé le sol en partie du jeu et nous a gardés tous les deux détendus.","On a commencé avec une balle, en la lançant d'une main à l'autre sur le beat, pics à hauteur des yeux. Ça semblait trop facile pendant environ trois sessions, puis soudain important, parce que les échanges à deux balles ne fonctionnent que si ces lancers simples sont réguliers. Elle a réussi l'échange avant moi et était insupportable à ce sujet.","La musique comptée nous a aidés à pratiquer ensemble. Même tempo, même downbeat, deux personnes qui lancent en rythme. Quand l'un de nous perdait le pattern, l'autre continuait, et celui qui avait fait tomber revenait au prochain « un ».","Quatre semaines plus tard, on a tous les deux une cascade bancale. Plus important encore, on a une habitude qu'on attend tous les deux avec impatience. Si vous avez un enfant qui veut apprendre quelque chose, apprenez-le avec lui. Être débutant ensemble est sous-estimé."]},"why-your-throws-drift-forward":{"title":"Pourquoi tes lancers dérivent vers l'avant","summary":"Si tu termines chaque cascade trois pas plus loin que ton point de départ, tes lancers penchent loin de toi. Voici comment les ramener à la maison.","body":["Chaque jongleur connaît la marche. Tu commences la cascade au milieu de la pièce et tu la termines le nez contre le mur, poursuivant le motif pas à pas. On a l'impression que les balles te tirent. Ce n'est pas le cas. Tu les lances vers l'avant, quelques centimètres à la fois, puis tu marches pour rattraper.","La cause, ce sont presque toujours les coudes. Quand tu te crispes, les avant-bras basculent vers l'avant et les mains lâchent la balle légèrement devant le corps. Chaque lancer atterrit un peu plus loin, donc la prochaine réception se fait plus loin, donc le prochain lancer part de plus loin. Ça s'amplifie vite.","Le correctif que j'enseigne en premier, c'est de rentrer les coudes. Garde les coudes près des côtes, les avant-bras à peu près à l'horizontale, et lance les balles droit vers le haut, au-delà de tes yeux, plutôt que devant toi. Ça semble serré pendant une journée. Ensuite, ça semble calme.","Le deuxième correctif, c'est un mur. Tiens-toi face à lui, à environ un avant-bras de distance, et jongle. Si les lancers dérivent, le mur te le dit immédiatement, et fort. Dix minutes de pratique contre le mur apprennent au corps ce qu'est un motif bien vertical plus vite que tout ce que je peux dire.","Le mode caméra de SynthFlow surveille aussi la dérive. Il suit à quel point ton torse paraît plus grand à la caméra au fil d'un pas, ce qui signifie que tu marches vers elle, et te pousse avec un court signal. Le coach 3D peut aussi montrer le fantôme d'un lancer vers l'avant à côté du lancer propre, pour que tu voies la différence au lieu de simplement en entendre parler.","La dérive n'est pas un défaut de caractère. C'est une habitude de tension, et les habitudes changent avec la répétition. Rentrer les coudes, lancer vers le haut et non vers l'avant, et laisse le mur te garder honnête."]},"practising-to-a-click":{"title":"Pratiquer sur un clic","summary":"Un métronome, ça semble être la chose la moins amusante du monde. Il s'est avéré que c'est ce qui a fait que mon flow ressemble à de la danse.","body":["J'ai résisté au clic pendant des années. La musique était l'essentiel du flow arts pour moi, et un métronome ressemblait à des devoirs. Puis une amie batteuse m'a regardé jongler et m'a dit, gentiment, que j'accélérais chaque fois que je m'enthousiasmais et que je ralentissais chaque fois que j'avais peur. Elle avait raison, et je n'en avais aucune idée.","Alors j'ai essayé une semaine de pratique avec rien d'autre qu'un clic. La première découverte, c'est qu'une pulsation régulière est plus difficile qu'il n'y paraît. Mon motif deux-en-une-main voulait se précipiter. Mon figure-8 au staff voulait traîner du côté faible. Le clic ne se souciait pas de ce que je ressentais ; il gardait juste le tempo.","La deuxième découverte, c'est que le clic rendait la musique plus facile. Après une semaine, quand j'ai remis de vrais morceaux, je pouvais sentir où le beat se trouvait dans le son. J'ai arrêté de me battre avec les chansons au timing flou et j'ai commencé à choisir sur quelle partie du groove me caler.","Les percussions générées par SynthFlow sont une version plus sympathique du clic. Tu choisis un kit, d'un simple clic aux tambours à main, et il joue à n'importe quel tempo, pour qu'un motif puisse vivre exactement à la vitesse que tu peux tenir. Il peut aussi tourner discrètement sous une piste musicale comme guide. Je l'utilise encore seul pour les premières minutes de chaque session.","Si tu veux essayer, choisis un motif et un tempo qui semble légèrement trop lent. Compte à voix haute pendant quatre mesures, puis arrête de compter et écoute simplement. Quand le motif et le clic semblent ne faire qu'un seul son, ajoute quatre BPM. C'est toute la méthode."]},"staff-in-a-small-apartment":{"title":"Le staff dans un petit appartement","summary":"Un staff de 1,4 mètre et un plafond de 2,4 mètres peuvent vivre ensemble. Il faut juste choisir ses plans.","body":["Mon appartement a des plafonds bas, une suspension à laquelle je tiens, et un voisin du dessous qui travaille de nuit. Rien de tout ça n'est idéal pour le staff. J'ai pratiqué dans les parcs pendant un an avant de comprendre que la plupart de mon entraînement pouvait finalement se faire à l'intérieur.","L'astuce, ce sont les plans. Les spins dans le plan de la roue, les grands à côté du corps, ont besoin de toute la hauteur du staff au-dessus de ta tête. Le travail dans le plan du mur, devant le corps, a besoin de largeur mais de moins de hauteur. Les spins dans le plan du sol, comme l'hélicoptère, ont besoin de dégagement au-dessus de ta tête mais de rien autour des tibias. Chaque pièce supporte des mouvements différents.","Dans mon salon, je peux faire des isolations, des spins avant et des figure-8 lents avec les bras bas. Dans le couloir, je ne peux rien faire du tout, donc le couloir sert aux échauffements des poignets. La chambre a le plafond le plus haut, donc le travail dans le plan de la roue s'y fait, lentement, avec la suspension retirée et rangée dans un tiroir.","Les staffs courts aident aussi. Un staff d'entraînement plus court d'une main que mon staff de performance a transformé beaucoup de quasi-accidents en dégagements faciles. Le timing change un peu, donc je vérifie mon staff pleine longueur dehors une fois par semaine.","Pour les voisins : tapis de pratique et staffs à embouts souples. Une chute sur un tapis de yoga fait un bruit sourd au lieu d'un claquement. Je limite aussi les sessions intérieures à des routines comptées de dix minutes, ce qui garde le bruit court et la pratique concentrée.","SynthFlow te permet de marquer les mouvements que tu ne peux pas faire chez toi comme non désirés, pour que le générateur les laisse hors des routines intérieures. Les petits espaces n'arrêtent pas le progrès. Ils te rendent juste très bon en isolations."]},"hooping-after-40":{"title":"Le hooping après 40 ans","summary":"J'ai pris un hoop pour la première fois à 43 ans. Mon dos, mes genoux et ma fierté avaient tous des opinions. Voici ce qui a marché.","body":["J'ai acheté mon premier hoop adulte sur un coup de tête après un festival, convaincu que je serais nul. J'étais nul. J'étais aussi, en un mois, en train de hooper à la taille pendant des chansons entières, et en six mois je faisais de simples mouvements hors du corps. L'âge ne m'a pas arrêté. Il a juste changé ma façon de devoir pratiquer.","La grande leçon était de bien s'échauffer. Les cercles de hanches, les torsions du buste et les petits rebonds de genoux prennent trois minutes et font que le premier hoop de la session semble fluide au lieu de grinçant. SynthFlow place les échauffements au début de chaque routine pour une raison, et j'ai arrêté de les sauter après une matinée raide.","La deuxième leçon était la taille du hoop. Un hoop plus grand et légèrement plus lourd tourne plus lentement, ce qui te donne plus de temps et demande moins d'effort au bas du dos. J'ai commencé avec un hoop qui atteignait entre ma taille et ma poitrine posé au sol, et je l'utilise encore pour les longues sessions.","Troisième : pulse, ne fais pas de cercle. Les débutants balancent souvent les hanches en cercle, ce qui tord la colonne plus que nécessaire. Une pulsation avant-arrière, ou latérale si le hoop tourne dans ce sens pour toi, garde le hoop en haut avec moins de tension. Le coach 3D le montre clairement si tu regardes les hanches plutôt que le hoop.","Enfin, court et souvent bat long et occasionnel. Dix minutes quatre fois par semaine m'ont plus apporté qu'une heure le dimanche. Mon corps récupérait entre les sessions, et les mouvements restaient.","Si tu as plus de 40 ans et que tu es curieux, commence. Le hoop ne sait pas quel âge tu as."]},"fire-and-the-beginner":{"title":"Le feu et le débutant","summary":"Le fire spinning est la partie la plus visible du flow arts et celle sur laquelle les débutants posent le plus de questions. La réponse honnête est : pas encore, et pas seul.","body":["Chaque semaine, quelqu'un nous demande quand SynthFlow enseignera le feu. C'est une question légitime. Le feu est beau, et beaucoup de spinners sont entrés dans le milieu après avoir vu un cercle de feu la nuit. Mais nous ne coacherons jamais quelqu'un pour allumer un prop, et ce post explique pourquoi.","Le feu ajoute des dangers qui n'ont rien à voir avec la compétence : manipulation du carburant, vêtements, vent, spectateurs, brûlures et extinction. Tout ça s'apprend de personnes expérimentées en personne, avec une personne de sécurité formée présente et l'équipement adéquat prêt. Une app ne peut pas vérifier ta réserve de carburant, tes vêtements en coton ou ta serviette de sécurité.","Ce que l'app peut faire, c'est t'aider à construire les compétences dont le feu a besoin avant même que tu t'en approches. Ça veut dire des mouvements que tu peux faire de façon fiable pendant une chanson entière, à un tempo régulier, sans chutes. Si un motif te surprend encore chez toi avec un prop d'entraînement, il n'est pas prêt pour le feu.","Un test utile venu de la communauté du feu : peux-tu exécuter ta routine les yeux à moitié fermés, dans le noir, pendant que quelqu'un te parle ? Le feu est lumineux, chaud et bruyant, et il capte ton attention. Ton corps doit connaître les mouvements sans surveillance.","Les props LED sont une excellente étape intermédiaire. Ils te donnent le look nocturne, les traînées et la réaction du public sans le risque. Le pack de style LED de SynthFlow montre à quoi ressembleront tes figures une fois éclairées, ce qui est aussi un bon moyen de repérer les plans approximatifs.","Quand tu te sens prêt, trouve un fire jam près de chez toi, présente-toi et demande à apprendre la sécurité en premier. En attendant, entraîne-toi avec des props de practice. Le feu sera toujours là."]},"four-balls-taught-me-patience":{"title":"Quatre balles m'ont appris la patience","summary":"Passer de trois balles à quatre m'a pris plus de temps que d'apprendre les trois au départ, et cela a changé ma façon de concevoir la pratique.","body":["Trois balles m'ont pris cinq semaines. Quatre m'ont pris cinq mois. Personne ne m'avait prévenu, alors je te préviens : quatre balles, ce n'est pas trois balles plus une. C'est une figure complètement différente, et ton corps doit l'apprendre de zéro.","Dans une fontaine à quatre balles, chaque main jongle deux balles de son côté, et les balles ne se croisent jamais. Les mains alternent généralement, mais il n'y a aucun échange entre elles. Tout ce que j'avais appris sur la réception d'une balle venant de l'autre main devenait soudain inutile.","Alors je suis revenu à une main. Deux balles dans la main droite, en colonnes, puis en cercles, jusqu'à pouvoir faire cinquante lancers sans réfléchir. Puis la main gauche, qui a pris trois fois plus de temps. Puis les deux mains ensemble, d'abord en sync, puis en alterné. L'échelle de tempo dans SynthFlow m'a aidé ici : je commençais chaque semaine en bas de la plage de la fontaine et je ne montais qu'après une série propre.","La leçon de patience est venue des plateaux. Certaines semaines, rien ne progressait. J'enregistrais quand même les chutes et les séries propres, et le graphique montrait une lente progression même quand je n'en ressentais aucune. Les données rendaient les semaines ennuyeuses supportables.","L'autre leçon concernait le repos. Quatre balles fatiguaient mes avant-bras d'une manière que trois n'avaient jamais fait. Quand je pratiquais tous les jours, je régressais. Quand je pratiquais un jour sur deux, je progressais. Les muscles de la prise ont besoin de récupération comme les autres.","Si tu es bloqué entre trois et quatre, découpe le problème, fais confiance aux semaines lentes et donne un jour de repos à tes avant-bras. Ça finit par arriver."]},"the-escalator-and-hand-traffic":{"title":"L'escalator et l'art du trafic des mains","summary":"Les mouvements de mains au hooping ressemblent à de la magie jusqu'à ce que tu comprennes qu'ils ne sont qu'une gestion minutieuse du trafic entre deux mains.","body":["La première fois que j'ai vu un escalator, le hoop semblait monter le long des bras de la hoopeuse et redescendre en flottant, sans fin, sans prise évidente. Je pensais qu'il fallait des années de pratique. Il a fallu environ trois semaines, une fois que j'ai compris que ce n'est qu'un enchaînement de passes de main.","Presque tous les mouvements de hoop off-body reposent sur quelle main tient le hoop, quand elle lâche, et où l'autre main le rejoint. Si le timing entre les mains est flou, le hoop vacille hors de son plan et le mouvement s'effondre. Si le timing est propre, le hoop semble bouger tout seul.","Alors j'ai commencé à nommer les passes. Sur le compte de SynthFlow, je disais les mains à voix haute au lieu des chiffres : droite, gauche, droite, gauche, une sur chaque temps. Les dire avec la musique m'obligeait à remarquer quand ma main gauche attrapait trop tôt. Les prises précoces étaient la source de presque toutes les vacillations.","La deuxième clé était de garder le hoop dans son plan. Une main qui pivote en saisissant incline le hoop, et un hoop incliné est un hoop échappé une demi-seconde plus tard. L'overlay de plan aide ici, tout comme s'entraîner devant un miroir à tempo lent.","Une fois l'escalator fiable, les autres mouvements de mains sont venus plus vite. Isolations, passes et lassos utilisent tous la même idée : passes claires, plans plats, timing régulier. La magie n'est que de la gestion de trafic."]},"behind-the-back-without-fear":{"title":"Derrière le dos sans peur","summary":"Les passes de staff derrière le dos sont le point où la plupart des spinners calent. Le problème n'est généralement pas la compétence mais l'envie de regarder.","body":["Pendant des mois, ma passe derrière le dos était une passe devant avec une torsion pleine d'espoir. Je lançais le mouvement, paniquais quand le staff quittait mon champ de vision, et le ramenais devant moi. Le staff ne passait jamais réellement derrière mon dos. Mon cerveau ne le permettait pas.","Le déclic est venu en acceptant que je ne pouvais pas voir le mouvement. On ne peut pas regarder une passe derrière le dos. Il faut sentir où est le staff depuis la main qui lâche et faire confiance à la main qui attend.","J'ai entraîné cette sensation au ralenti. Sans spinner du tout, je passais le staff derrière mon dos, de main en main, les yeux vers l'avant. Puis avec un lent demi-tour d'abord. Puis en bas de la plage de tempo du mouvement, en comptant. Chaque étape semblait ridicule. Chaque étape fonctionnait.","Le coach 3D était étonnamment utile parce que je pouvais faire pivoter la vue et regarder le mouvement depuis l'arrière. Voir où les mains se rejoignent, et comment le staff reste dans le plan du mur en tournant, a donné à mon corps une carte qu'il ne pouvait pas obtenir de face.","La deuxième peur était de me frapper. Un staff de practice à embouts souples et un grand espace dégagé ont résolu ça. Une fois que je savais qu'une erreur coûterait un léger choc plutôt qu'un bleu, j'ai arrêté de tressaillir, et c'était le tressaillement qui causait les ratés.","Si le derrière du dos te fait encore peur, ralentis vraiment, enlève la rotation et garde les yeux vers l'avant. Tes mains en savent plus que tu ne le penses."]},"why-reverse-feels-wrong":{"title":"Pourquoi la cascade inversée semble bizarre","summary":"La cascade inversée utilise les mêmes mains, les mêmes balles et le même rythme que la cascade. Alors pourquoi donne-t-elle l'impression de repartir de zéro ?","body":["Quand j'ai appris la cascade inversée, je pensais que ça prendrait un après-midi. C'est les mêmes trois balles, les mêmes mains en alternance et le même tempo que la cascade. Ça m'a pris trois semaines, et je n'arrivais pas à comprendre pourquoi.","La réponse est la direction. Dans une cascade normale, chaque balle est lancée depuis l'intérieur de la figure et rattrapée à l'extérieur. Dans une cascade inversée, la balle est lancée depuis l'extérieur, par-dessus la balle qui arrive, et rattrapée à l'intérieur. Tes mains font le même rythme mais des formes complètement différentes.","La nouvelle forme casse ton timing. Dans la cascade, tu lances juste au moment où la balle qui arrive commence à retomber. Dans l'inversée, tu dois lancer un peu plus tôt pour que ta balle passe au-dessus de l'autre. Lance au moment habituel et les balles se percutent.","J'ai corrigé ça avec deux balles d'abord. Deux balles, direction inversée, en comptant sur le temps, jusqu'à ce que ce soit automatique. Puis trois balles à tempo lent avec les comptes dits à voix haute. L'overlay fantôme de SynthFlow m'a montré une erreur typique, un lancer trop bas qui accroche l'autre balle, et je pouvais voir que je faisais exactement ça.","Une fois le déclic passé, ça a tout débloqué. Mélanger cascade et inversée est la base de nombreux tricks, et la forme inversée réapparaît dans le Mills Mess. Avoir été mauvais pendant trois semaines en valait la peine."]},"making-a-prop-stand-still":{"title":"Les isolations : faire tenir un prop immobile","summary":"Une isolation est un mouvement où le prop semble rester au même endroit pendant que tu tournes autour de lui. C'est l'illusion la plus satisfaisante des flow arts.","body":["La première fois que j'ai réussi une isolation au staff, mon ami m'a demandé comment le staff flottait. Il ne flottait pas, bien sûr. Mes mains décrivaient un cercle précis pour qu'un point du staff reste fixe dans l'air. Mais de l'extérieur, ça semblait impossible, et c'est ce sentiment qui me fait aimer les isolations.","Chaque isolation fonctionne de la même façon. Choisis un point sur le prop, généralement le centre ou une extrémité, et garde ce point immobile pendant que le reste du prop tourne. Tes mains doivent bouger exactement à l'opposé de la direction que le prop veut prendre. C'est contre-intuitif et légèrement hypnotique.","Le plus dur, c'est que ton corps bouge aussi. Les hanches se décalent, les épaules tournent, et chaque petit mouvement se traduit par un vacillement du point fixe. Je m'entraînais devant un miroir avec un morceau de ruban adhésif sur la vitre marquant l'endroit où le point fixe devait rester. Si le centre du prop quittait le ruban, je le savais.","Les isolations au hoop suivent la même idée. Dans SynthFlow, j'active les traînées dans la visionneuse 3D et je regarde le coach : dans une isolation propre, la traînée autour du point fixe reste minuscule. Quand je ralentissais vraiment le tempo et copiais, je sentais mes mains dériver en haut de chaque cercle.","Les isolations développent aussi un contrôle qui aide tout le reste. Une fois que tu peux tenir un prop immobile, tu peux le placer où tu veux. Les plans deviennent plus plats, les transitions plus propres, et ton flow commence à sembler intentionnel plutôt que chanceux.","Commence lentement, marque le point fixe et surveille-le comme un faucon. Ensuite, montre-le à un ami et savoure sa réaction."]}}`),i={"zero-to-cascade":{name:`De zéro à la cascade en 4 semaines`,description:`Une balle, puis deux, puis la troisième rejoint. Une courte session par jour suffit : terminez la routine de chaque semaine pour maîtriser son mouvement et ouvrir la suivante.`,weeks:[{label:`Semaine 1 · Une balle`},{label:`Semaine 2 · Deux balles`},{label:`Semaine 3 · La troisième balle`},{label:`Semaine 4 · Cascade`}]},"staff-foundations":{name:`Les fondations du staff`,description:`Wheel spin et front spin, le figure 8 et le pass-through : les quatre mouvements sur lesquels presque tout le flow au staff se construit.`,weeks:[{label:`Semaine 1 · Wheel spin`},{label:`Semaine 2 · Front spin`},{label:`Semaine 3 · Figure 8`},{label:`Semaine 4 · Pass-through`}]},"off-body-hoop":{name:`Hoop off-body`,description:`Du hoop qui tourne sur une main aux lassos, passes, wedgies et à l'isolation qui fait sembler le hoop flotter.`,weeks:[{label:`Semaine 1 · Hand spin`},{label:`Semaine 2 · Lasso et pass`},{label:`Semaine 3 · Wedgie`},{label:`Semaine 4 · Isolation`}]}},a={"sf-ambient-70":{name:`Orbite lente`},"sf-world-75":{name:`Pas de marché`},"sf-ambient-80":{name:`Dérive de lanterne`},"sf-world-85":{name:`Roue du désert`},"sf-handdrum-90":{name:`Tambour circulaire`},"sf-funk-95":{name:`Poignets souples`},"sf-handdrum-100":{name:`Mains de feu`},"sf-world-105":{name:`Cloches de rivière`},"sf-funk-110":{name:`Cascade de poche`},"sf-handdrum-115":{name:`Groove de cour`},"sf-electronic-120":{name:`Staff néon`},"sf-funk-125":{name:`Motif rebond`},"sf-electronic-130":{name:`Hoop Pixel`},"sf-handdrum-135":{name:`Djembé coucher de soleil`},"sf-electronic-140":{name:`Traînées LED`},"sf-funk-145":{name:`Cycle de rotation`},"sf-electronic-150":{name:`Flow stroboscopique`},"sf-handdrum-155":{name:`Paumes rapides`},"sf-electronic-160":{name:`Spinner nocturne`}},o={poses:e,routines:t,learn:n,blog:r,progressions:i,music:a};export{r as blog,o as default,n as learn,a as music,e as poses,i as progressions,t as routines};